    /**
     * 实时动态检索项目维表列表（供 A2UI 交互下拉菜单与实时模糊搜索使用，0 硬编码）
     */
    async function searchProjectList(searchQuery, state, win) {
        const clean = (searchQuery || '').trim();
        try {
            if (!state.applicantId) {
                try {
                    await fetchLoginUserInfo(state);
                }
                catch (e) { }
            }
            const payload = {
                dimObjectId: TRIP_CONSTANTS.projectDimObjectId,
                searchInfo: clean,
                isParentId: false,
                isShowDisable: false,
                isFastShow: true,
                isShowCode: true,
                isShowRootNode: false,
                isSynchronize: false,
                permDataScope: 'BILL_ENTRY',
                loginUserId: state.applicantId || '11eee047a80566bca18367ceb209b2e1',
                isUseSecurityFormal: false
            };
            // 优先尝试原生 HTTP 客户端 (100% 鉴权与 Cookie)
            let res = await callNativeHttp('/dim/dimObject/getDimObjectAccessTree', 'POST', payload, win);
            if (!res || !res.success) {
                res = await apiRequest('/fssc/dim/dimObject/getDimObjectAccessTree', 'POST', payload, state);
            }
            const list = [];
            if (res && res.success && res.data && Array.isArray(res.data)) {
                const traverse = (nodes) => {
                    nodes.forEach(node => {
                        const d = node.data || node;
                        const id = d.objectId || d.id || node.id || node.key;
                        const name = d.description || d.name || node.name || (d.externalSysAttr?.NAME) || '';
                        const code = d.code || node.code || (d.externalSysAttr?.CODE) || '';
                        if (id && (name || code)) {
                            list.push({
                                id,
                                code,
                                name,
                                vo: {
                                    value: id,
                                    title: { zh_CN: name }
                                }
                            });
                        }
                        if (node.children && Array.isArray(node.children) && node.children.length > 0) {
                            traverse(node.children);
                        }
                    });
                };
                traverse(res.data);
                return list;
            }
        }
        catch (e) {
            AutopilotLogger.warn(`[searchProjectList] 检索项目列表失败: ${e.message}`);
        }
        return [];
    }
    /**
     * 通用日期数学计算：根据起止日期计算出差天数与间夜数
     */
    function calculateDaysAndNights(startDate, endDate) {
        try {
            const start = new Date(startDate.replace(/-/g, '/'));
            const end = new Date(endDate.replace(/-/g, '/'));
            if (isNaN(start.getTime()) || isNaN(end.getTime())) {
                return { days: 1, nights: 0 };
            }
            const diffMs = end.getTime() - start.getTime();
            const days = Math.max(1, Math.round(diffMs / (1000 * 3600 * 24)) + 1);
            const nights = Math.max(0, days - 1);
            return { days, nights };
        }
        catch {
            return { days: 1, nights: 0 };
        }
    }
    /**
     * 计算误餐补助金（依据通用企业差旅规程：首末往返半天各按半额计算，整日按全额计算）
     */
    function computeMealAllowance(days, standardDaily = 300, travelHalfDay = 150) {
        if (days <= 0)
            return 0;
        if (days === 1)
            return travelHalfDay;
        if (days === 2)
            return travelHalfDay * 2;
        return travelHalfDay * 2 + (days - 2) * standardDaily;
    }
    /**
     * 动态单据装配引擎：基于动态行程输入组装完整的单据配置
     */
    function createDynamicTripConfig(input, defaultCityBuffer = 100, defaultTrafficBuffer = 0.15, index = 1) {
        const { days, nights } = calculateDaysAndNights(input.startDate, input.endDate);
        // 住宿差标智能推断：一线城市（北上广深）按 ¥800，其他按 ¥700
        const tier1Cities = ['北京', '上海', '广州', '深圳'];
        const isTier1 = tier1Cities.some(c => (input.destination || '').includes(c));
        const hotelRate = input.hotelPricePerNight ?? (isTier1 ? 800 : 700);
        const hotelFee = nights * hotelRate;
        // 误餐补助
        const mealFee = computeMealAllowance(days);
        // 市内交通与不可预见 Buffer
        const cityBufRate = input.cityBufferPerDay ?? defaultCityBuffer;
        const otherFee = days * cityBufRate;
        // 交通票价与改签 Buffer
        const baseTraffic = input.baseTrafficFee ?? 0;
        const trafficBufPercent = input.trafficBufferPercent ?? defaultTrafficBuffer;
        const trafficBuffer = Math.round(baseTraffic * trafficBufPercent);
        const trafficFee = baseTraffic + trafficBuffer;
        const totalAmount = trafficFee + hotelFee + mealFee + otherFee;
        // 往返程航线/车次生成（若未提供，自动生成默认始发与往返程）
        let legs = input.legs;
        if (!legs || legs.length === 0) {
            const traveler = input.applicantName || '当前用户';
            const flight = input.flightOrTrain || '飞机/高铁';
            legs = [
                { date: input.startDate, fromCity: '上海', toCity: input.destination, transport: flight, travelerName: traveler },
                { date: input.endDate, fromCity: input.destination, toCity: '上海', transport: flight, travelerName: traveler }
            ];
        }
        else {
            // 确保每条 leg 均记录 travelerName
            legs = legs.map(l => ({
                ...l,
                travelerName: l.travelerName || input.applicantName || '当前用户'
            }));
        }
        const tripNo = input.tripNo || index;
        const proxyTag = input.isProxy ? `(代办)` : `(本人)`;
        const defaultPurpose = input.purpose || `${input.destination}业务差旅与实地调研 ${proxyTag}`;
        const feeFormulas = {
            trafficFormula: `往返大交通基准 (¥${baseTraffic.toLocaleString()}) + 改签弹性${Math.round(trafficBufPercent * 100)}% (¥${trafficBuffer.toLocaleString()}) = ¥${trafficFee.toLocaleString()}`,
            hotelFormula: `${nights}晚 × ¥${hotelRate}/晚 (${isTier1 ? '一线城市限额¥800' : '二三线城市限额¥700'}) = ¥${hotelFee.toLocaleString()}`,
            mealFormula: `${days}天差旅误餐生活补助 (往返乘车日各半额¥150，整天调研¥300) = ¥${mealFee.toLocaleString()}`,
            otherFormula: `${days}天市内出租车/网约车预留 (¥${cityBufRate}/天) = ¥${otherFee.toLocaleString()}`,
            totalFormula: `大交通 ¥${trafficFee.toLocaleString()} + 酒店住宿 ¥${hotelFee.toLocaleString()} + 误餐补助 ¥${mealFee.toLocaleString()} + 市内Buffer ¥${otherFee.toLocaleString()} = ¥${totalAmount.toLocaleString()}`
        };
        return {
            id: input.id || `TRIP-${tripNo}-${input.applicantName}-${Math.random().toString(36).slice(2, 6)}`,
            tripNo,
            applicantName: input.applicantName,
            isProxy: Boolean(input.isProxy),
            travelers: input.travelers || [input.applicantName],
            isCombined: Boolean(input.isCombined),
            startDate: input.startDate,
            endDate: input.endDate,
            days,
            nights,
            destination: input.destination,
            targetFactories: input.targetFactories || '',
            hotelName: input.hotelName || '',
            purpose: defaultPurpose,
            trafficFee,
            hotelFee,
            mealFee,
            otherFee,
            trafficBuffer,
            totalAmount,
            legs,
            feeFormulas,
            projectVO: input.projectVO,
            projectName: input.projectName,
            status: '就绪'
        };
    }
    /**
     * 解析活动日程时间线表格 (Timeline Activity Table)
     * 严格遵循核心规约：
     * - 【有住宿 即为出差】：只要活动包含酒店住宿安排，即确认为独立出差（含上海金山园区等近郊有住宿出差）；
     * - 【同一目的城市 往返多次 则视为多轮出差，不应该合并】：按往返闭环（从上海出发，返回上海）切分独立出差轮次。
     */
    function parseTimelineActivityTable(lines, delimiter, indices) {
        const normalizeDate = (d) => {
            const clean = (d || '').trim().replace(/\//g, '-');
            const match = clean.match(/(\d{4})[^\d]+(\d{1,2})[^\d]+(\d{1,2})/);
            if (match) {
                const m = match[2].padStart(2, '0');
                const day = match[3].padStart(2, '0');
                return `${match[1]}-${m}-${day}`;
            }
            return clean;
        };
        const rawRows = [];
        for (const line of lines) {
            const cells = line.split(delimiter).map(c => c.trim().replace(/^\||\|$/g, ''));
            if (cells.length < 2)
                continue;
            const getVal = (idx) => (idx !== -1 && idx < cells.length ? cells[idx].trim() : '');
            const type = getVal(indices.typeIdx);
            const city = getVal(indices.cityIdx);
            const factory = getVal(indices.factoryIdx);
            const company = getVal(indices.companyIdx);
            const startDate = normalizeDate(getVal(indices.startIdx));
            const endDate = normalizeDate(getVal(indices.endIdx)) || startDate;
            const nameRaw = getVal(indices.nameIdx);
            const origin = getVal(indices.originIdx);
            const dest = getVal(indices.destIdx);
            const transport = getVal(indices.transportIdx);
            const hotel = getVal(indices.hotelIdx);
            const travelers = nameRaw
                ? nameRaw.split(/[,，、\s]+/).map(n => n.trim()).filter(Boolean)
                : [];
            if (startDate) {
                rawRows.push({
                    type,
                    city: city.replace(/[-—]/g, ''),
                    factory: factory.replace(/[-—]/g, ''),
                    company: company.replace(/[-—]/g, ''),
                    startDate,
                    endDate,
                    travelers,
                    origin: origin.replace(/[-—]/g, ''),
                    dest: dest.replace(/[-—]/g, ''),
                    transport: transport.replace(/[-—]/g, ''),
                    hotel: hotel.replace(/[-—]/g, '')
                });
            }
        }
        if (rawRows.length === 0)
            return [];
        // 按往返闭环与有住宿条件切分出差轮次 (Trip Blocks)
        const blocks = [];
        let currentBlock = [];
        const isBaseCity = (c) => (c || '').includes('上海');
        for (let i = 0; i < rawRows.length; i++) {
            const row = rawRows[i];
            const isOutbound = isBaseCity(row.origin) && Boolean(row.dest) && !isBaseCity(row.dest);
            const isInbound = Boolean(row.origin) && !isBaseCity(row.origin) && isBaseCity(row.dest);
            const hasHotel = Boolean(row.hotel && row.hotel !== '-');
            // 当遇到从始发城市出发的移动，且当前 block 已有内容时，关闭前一个 block，开启新 block
            if (isOutbound && currentBlock.length > 0) {
                blocks.push(currentBlock);
                currentBlock = [row];
                continue;
            }
            // 如果当前没有正在构建的 block，若该行有出差特征（从始发地出发、或有酒店住宿、或有异地活动），开启新 block
            if (currentBlock.length === 0) {
                if (isOutbound || hasHotel || (row.city && !isBaseCity(row.city))) {
                    currentBlock.push(row);
                }
                continue;
            }
            // 将当前行加入 block
            currentBlock.push(row);
            // 如果该行是返回常驻地的移动，说明本轮往返闭环完成，立即封口当前 block！
            if (isInbound) {
                blocks.push(currentBlock);
                currentBlock = [];
            }
        }
        if (currentBlock.length > 0) {
            blocks.push(currentBlock);
        }
        // 将各 block 转化为标准的 DynamicTripInput
        const trips = [];
        let tripCounter = 1;
        for (const blk of blocks) {
            // 核心规约 1: 【有住宿 即为出差】
            const hotels = Array.from(new Set(blk.map(r => r.hotel).filter(Boolean)));
            const hasHotel = hotels.length > 0;
            const hasOutbound = blk.some(r => isBaseCity(r.origin) && r.dest && !isBaseCity(r.dest));
            // 既无住宿又无往返异地交通的本地日常无意义行过滤
            if (!hasHotel && !hasOutbound) {
                continue;
            }
            // 提炼目的地城市
            let destination = '';
            const cities = blk.map(r => r.city).filter(Boolean);
            const destCities = blk.map(r => r.dest).filter(d => d && !isBaseCity(d));
            if (destCities.length > 0) {
                destination = destCities[0];
            }
            else if (cities.length > 0) {
                destination = cities[0];
            }
            else {
                destination = '外地调研';
            }
            // 同城有住宿特殊处理（例如上海市金山区）
            if (destination.includes('上海') && blk.some(r => (r.factory + r.company + r.hotel).includes('金山'))) {
                destination = '上海金山';
            }
            destination = destination.replace(/省|市/g, '');
            // 统计起止日期
            const allStarts = blk.map(r => r.startDate).sort();
            const allEnds = blk.map(r => r.endDate).sort();
            const startDate = allStarts[0];
            const endDate = allEnds[allEnds.length - 1];
            // 汇总出行人
            const allTravelers = Array.from(new Set(blk.flatMap(r => r.travelers).filter(Boolean)));
            // 收集工厂与据点
            const factories = Array.from(new Set(blk.flatMap(r => [r.factory, r.company]).filter(Boolean)));
            // 核心规约：每位出行人员各自的实际起止周期识别（如李建勇 7/21 出发、陈浩 8/20 返程、成勇/李建勇 8/21 返程）
            const travelerPeriods = new Map();
            allTravelers.forEach(t => {
                const tRows = blk.filter(r => r.travelers.includes(t));
                if (tRows.length > 0) {
                    const starts = tRows.map(r => r.startDate).sort();
                    const ends = tRows.map(r => r.endDate).sort();
                    travelerPeriods.set(t, { start: starts[0], end: ends[ends.length - 1] });
                }
            });
            // 收集往返航线/车次
            const legs = [];
            blk.forEach(r => {
                if (r.origin && r.dest) {
                    const transport = r.transport || '飞机/高铁';
                    const travelers = r.travelers.length > 0 ? r.travelers : (allTravelers.length > 0 ? allTravelers : ['当前用户']);
                    travelers.forEach(t => {
                        legs.push({
                            date: r.startDate,
                            fromCity: r.origin,
                            toCity: r.dest,
                            transport,
                            travelerName: t
                        });
                    });
                }
            });
            // 针对未在显式移动行中的人员，按其在该波次中的实际最早出现日期与最后结束日期补齐往返
            allTravelers.forEach(t => {
                const period = travelerPeriods.get(t) || { start: startDate, end: endDate };
                const hasOutbound = legs.some(l => l.travelerName === t && (isBaseCity(l.fromCity) || !isBaseCity(l.toCity)));
                const hasInbound = legs.some(l => l.travelerName === t && (isBaseCity(l.toCity) || !isBaseCity(l.fromCity)));
                if (!hasOutbound) {
                    legs.push({
                        date: period.start,
                        fromCity: '上海',
                        toCity: destination,
                        transport: '飞机/高铁',
                        travelerName: t
                    });
                }
                if (!hasInbound) {
                    legs.push({
                        date: period.end,
                        fromCity: destination,
                        toCity: '上海',
                        transport: '飞机/高铁',
                        travelerName: t
                    });
                }
            });
            legs.sort((a, b) => new Date(a.date.replace(/-/g, '/')).getTime() - new Date(b.date.replace(/-/g, '/')).getTime());
            const hotelDisplay = hotels.join(' / ');
            const factoryDisplay = factories.join('、');
            const purpose = `${destination}业务差旅与实地调研` + (factoryDisplay ? ` (${factoryDisplay})` : '');
            trips.push({
                tripNo: tripCounter++,
                applicantName: allTravelers[0] || '当前用户',
                travelers: allTravelers,
                isProxy: false,
                destination,
                startDate,
                endDate,
                purpose,
                targetFactories: factoryDisplay,
                hotelName: hotelDisplay,
                legs: legs.length > 0 ? legs : undefined
            });
        }
        return trips;
    }
    /**
     * 通用表格文本解析器：支持用户上传 CSV / TSV / 粘贴文本智能解析为动态行程列表
     */
    function parseItineraryTable(tableText) {
        const lines = tableText.trim().split(/\r?\n/).map(l => l.trim()).filter(Boolean);
        if (lines.length < 2)
            return [];
        // 分隔符识别 (逗号、制表符、竖线、连续空格)
        const firstLine = lines[0];
        let delimiter = ',';
        if (firstLine.includes('\t')) {
            delimiter = '\t';
        }
        else if (firstLine.includes('|')) {
            delimiter = '|';
        }
        else if (firstLine.includes(',')) {
            delimiter = ',';
        }
        else if (/\s{2,}/.test(firstLine)) {
            delimiter = /\s{2,}/;
        }
        else if (firstLine.includes(' ')) {
            delimiter = /\s+/;
        }
        const headers = firstLine.split(delimiter).map(h => h.trim().replace(/^\||\|$/g, ''));
        const findCol = (keywords) => headers.findIndex(h => keywords.some(k => h.includes(k)));
        const typeIdx = findCol(['类型', '类别', '活动类型', 'type']);
        const cityIdx = findCol(['省市', '省份', '城市', '地区', '据点省市']);
        const originIdx = findCol(['移动-起点', '起点', '始发', '出发地', 'from']);
        const destIdx = findCol(['移动-目的地', '目的地', '城市', '地点', '到达地', 'destination', 'city', 'to']);
        const startIdx = findCol(['起始日', '开始日', '出发', '开始', '起期', 'start', '日期', 'date']);
        const endIdx = findCol(['结束日', '截止日', '返程', '结束', '止期', 'end']);
        const nameIdx = findCol(['IV人员', '出行人', '姓名', '员工', '申请人', '人选', 'traveler', 'name']);
        const factoryIdx = findCol(['据点名', '据点', '工厂', '厂区']);
        const companyIdx = findCol(['公司名', '公司', '单位', '企业']);
        const transportIdx = findCol(['交通工具', '班次', '车次', '航班', '交通', '机票', 'FLIGHT', 'TRAIN', 'flight', 'train', 'tool']);
        const hotelIdx = findCol(['住宿酒店', '酒店', '住宿', '宾馆', 'hotel']);
        const tripNoIdx = findCol(['批次', '行程', '序号', '波次', 'trip', 'no', '#']);
        const feeIdx = findCol(['票价', '车费', '机票费', '费用', 'fee', 'price']);
        const purposeIdx = findCol(['事由', '目的', '项目', '调研', 'purpose']);
        // 判断是否为时间线流水表 (Timeline Activity Table: 包含移动/调查类型，或包含单独的起点/目的地/住宿酒店列)
        const isTimelineTable = typeIdx !== -1 || (originIdx !== -1 && destIdx !== -1) || (hotelIdx !== -1 && factoryIdx !== -1);
        if (isTimelineTable) {
            return parseTimelineActivityTable(lines.slice(1), delimiter, {
                typeIdx, cityIdx, originIdx, destIdx, startIdx, endIdx, nameIdx,
                factoryIdx, companyIdx, transportIdx, hotelIdx});
        }
        const results = [];
        for (let i = 1; i < lines.length; i++) {
            const row = lines[i].split(delimiter).map(c => c.trim().replace(/^\||\|$/g, ''));
            if (row.length < 2)
                continue;
            const applicantName = nameIdx !== -1 ? row[nameIdx] : '当前用户';
            const destination = destIdx !== -1 ? row[destIdx] : '';
            const startDate = startIdx !== -1 ? row[startIdx] : '';
            const endDate = endIdx !== -1 ? row[endIdx] : '';
            const baseTrafficFee = feeIdx !== -1 ? parseFloat(row[feeIdx].replace(/[^\d.]/g, '')) || 0 : 0;
            const flightOrTrain = transportIdx !== -1 ? row[transportIdx] : '';
            const purpose = purposeIdx !== -1 ? row[purposeIdx] : '';
            const hotelName = hotelIdx !== -1 ? row[hotelIdx] : '';
            const parsedTripNo = tripNoIdx !== -1 ? parseInt(row[tripNoIdx].replace(/[^\d]/g, ''), 10) || (results.length + 1) : (results.length + 1);
            if (destination && startDate && endDate) {
                results.push({
                    tripNo: parsedTripNo,
                    applicantName,
                    isProxy: false,
                    destination,
                    startDate,
                    endDate,
                    hotelName,
                    baseTrafficFee,
                    flightOrTrain,
                    purpose
                });
            }
        }
        return results;
    }
    /**
     * 将同批次/同目的地的行程按正社员合并为单张出差申请单
     * 遵循用户核心规约：
     * 1. 出差申请不必每人每个目的地提交，可以由正社员提交出差申请，含1个或多个外驻人员的出差预算一并申请；
     * 2. 旅程 (ITINERARY) 可以是多行，FLIGHT/TRAIN ETC. 字段中不仅填写班次，最后要备注出差人员名。
     * 3. 同一目的城市往返多次视为多轮出差，绝不能跨越往返周期合并！
     */
    function combineTripsForMainApplicant(inputs, mainApplicantName, cityBufferPerDay = 100, trafficBufferPercent = 0.15) {
        if (!inputs || inputs.length === 0)
            return [];
        // 1. 确定主申请人 (正社员)
        let defaultMain = (mainApplicantName || '').trim();
        if (!defaultMain) {
            // 优先寻找显式标记为本人 (isProxy === false) 的记录
            const selfInp = inputs.find(i => i.isProxy === false);
            defaultMain = selfInp ? selfInp.applicantName : inputs[0].applicantName;
        }
        // 2. 按批次/波次聚类
        // 如果输入明确带有 tripNo，且有相同 tripNo 的多条记录，按 tripNo 聚类
        // 否则按目的地及时间相近性 (出发日期相差 <= 2 天，且属于同一往返) 聚类
        const groups = [];
        const hasExplicitTripNo = inputs.some(i => typeof i.tripNo === 'number' && i.tripNo > 0);
        if (hasExplicitTripNo) {
            const map = new Map();
            inputs.forEach((inp, idx) => {
                const key = inp.tripNo ? `TRIP_${inp.tripNo}_${inp.destination || ''}` : `ITEM_${idx}`;
                if (!map.has(key))
                    map.set(key, []);
                map.get(key).push(inp);
            });
            map.forEach(grp => groups.push(grp));
        }
        else {
            const used = new Set();
            for (let i = 0; i < inputs.length; i++) {
                if (used.has(i))
                    continue;
                const grp = [inputs[i]];
                used.add(i);
                const destA = (inputs[i].destination || '').trim();
                const startA = new Date(inputs[i].startDate.replace(/-/g, '/')).getTime();
                for (let j = i + 1; j < inputs.length; j++) {
                    if (used.has(j))
                        continue;
                    const destB = (inputs[j].destination || '').trim();
                    const startB = new Date(inputs[j].startDate.replace(/-/g, '/')).getTime();
                    const isSameDest = destA === destB || destA.includes(destB) || destB.includes(destA);
                    // 同一目的城市往返多次视为多轮独立出差，严禁跨往返周期合并！只有出发时间相差 <= 2 天的同行人记录才合并
                    const isCloseDate = !isNaN(startA) && !isNaN(startB) && Math.abs(startA - startB) <= 2 * 24 * 3600 * 1000;
                    if (isSameDest && isCloseDate) {
                        grp.push(inputs[j]);
                        used.add(j);
                    }
                }
                groups.push(grp);
            }
        }
        // 3. 构建单据配置清单
        return groups.map((grp, idx) => {
            const tripNo = idx + 1;
            const allTravelers = Array.from(new Set(grp.flatMap(g => (g.travelers && g.travelers.length > 0) ? g.travelers : [g.applicantName]).filter(Boolean)));
            const destination = grp[0].destination || '';
            // 统一起止时间（取所有成员的最早出发和最晚返程）
            const sortedStarts = grp.map(g => g.startDate).filter(Boolean).sort();
            const sortedEnds = grp.map(g => g.endDate).filter(Boolean).sort();
            const minStartDate = sortedStarts[0] || grp[0].startDate;
            const maxEndDate = sortedEnds[sortedEnds.length - 1] || grp[0].endDate;
            const { days: totalDays, nights: totalNights } = calculateDaysAndNights(minStartDate, maxEndDate);
            // 住宿差标智能推断：一线城市（北上广深）按 ¥800，其他按 ¥700
            const tier1Cities = ['北京', '上海', '广州', '深圳'];
            const isTier1 = tier1Cities.some(c => destination.includes(c));
            let sumTrafficFee = 0;
            let sumTrafficBuffer = 0;
            let sumHotelFee = 0;
            let sumMealFee = 0;
            let sumOtherFee = 0;
            const allLegs = [];
            // 逐人精准测算各自在该行程中的费用并收集多行旅程明细
            grp.forEach(member => {
                const mTravelers = (member.travelers && member.travelers.length > 0)
                    ? member.travelers
                    : [member.applicantName];
                const { days: mDays, nights: mNights } = calculateDaysAndNights(member.startDate, member.endDate);
                const mHotelRate = member.hotelPricePerNight ?? (isTier1 ? 800 : 700);
                const mCityRate = member.cityBufferPerDay ?? cityBufferPerDay;
                const mBaseTraffic = member.baseTrafficFee ?? 0;
                const mTrafPercent = member.trafficBufferPercent ?? trafficBufferPercent;
                const mTrafBuf = Math.round(mBaseTraffic * mTrafPercent);
                const mTraffic = mBaseTraffic + mTrafBuf;
                // 核心规约：按实际出差的所有同行人员 (正社员 + 外驻) 独立测算个人出差周期与预算
                mTravelers.forEach(t => {
                    let tStart = member.startDate;
                    let tEnd = member.endDate;
                    if (member.legs && member.legs.length > 0) {
                        const cleanT = t.replace(/（.*）|\(.*\)/g, '').trim();
                        const tLegs = member.legs.filter(l => {
                            const lTrav = (l.travelerName || '').replace(/（.*）|\(.*\)/g, '').trim();
                            return lTrav === cleanT || (l.flightOrTrain && l.flightOrTrain.includes(cleanT));
                        });
                        if (tLegs.length > 0) {
                            const dates = tLegs.map(l => l.date).sort();
                            tStart = dates[0];
                            tEnd = dates[dates.length - 1];
                        }
                    }
                    const { days: tDays, nights: tNights } = calculateDaysAndNights(tStart, tEnd);
                    const tSingleMeal = computeMealAllowance(tDays);
                    sumHotelFee += tNights * mHotelRate;
                    sumMealFee += tSingleMeal;
                    sumOtherFee += tDays * mCityRate;
                    sumTrafficFee += mTraffic;
                    sumTrafficBuffer += mTrafBuf;
                });
                if (member.legs && member.legs.length > 0) {
                    const legsTravelers = new Set(member.legs.map(l => (l.travelerName || '').trim()).filter(Boolean));
                    const missingTravelers = mTravelers.filter(t => !legsTravelers.has(t.trim()));
                    member.legs.forEach(l => {
                        allLegs.push({
                            date: l.date,
                            fromCity: l.fromCity,
                            toCity: l.toCity,
                            transport: l.transport,
                            flightOrTrain: l.flightOrTrain,
                            travelerName: l.travelerName || member.applicantName
                        });
                    });
                    // 为尚未在 legs 中的同行外驻人员自动补全对称往返行程
                    missingTravelers.forEach(t => {
                        const sampleOut = member.legs.find(l => l.fromCity.includes('上海') || !l.toCity.includes('上海'));
                        const sampleIn = member.legs.find(l => l.toCity.includes('上海') || !l.fromCity.includes('上海'));
                        allLegs.push({
                            date: sampleOut ? sampleOut.date : member.startDate,
                            fromCity: sampleOut ? sampleOut.fromCity : '上海',
                            toCity: sampleOut ? sampleOut.toCity : destination,
                            transport: sampleOut ? sampleOut.transport : '飞机/高铁',
                            flightOrTrain: sampleOut?.flightOrTrain,
                            travelerName: t
                        });
                        allLegs.push({
                            date: sampleIn ? sampleIn.date : member.endDate,
                            fromCity: sampleIn ? sampleIn.fromCity : destination,
                            toCity: sampleIn ? sampleIn.toCity : '上海',
                            transport: sampleIn ? sampleIn.transport : '飞机/高铁',
                            flightOrTrain: sampleIn?.flightOrTrain,
                            travelerName: t
                        });
                    });
                }
                else {
                    const flight = member.flightOrTrain || '飞机/高铁';
                    mTravelers.forEach(t => {
                        allLegs.push({
                            date: member.startDate,
                            fromCity: '上海',
                            toCity: destination,
                            transport: flight,
                            flightOrTrain: member.flightOrTrain,
                            travelerName: t
                        });
                        allLegs.push({
                            date: member.endDate,
                            fromCity: destination,
                            toCity: '上海',
                            transport: flight,
                            flightOrTrain: member.flightOrTrain,
                            travelerName: t
                        });
                    });
                }
            });
            // 旅程按日期正序排列
            allLegs.sort((a, b) => new Date(a.date.replace(/-/g, '/')).getTime() - new Date(b.date.replace(/-/g, '/')).getTime());
            const totalAmount = sumTrafficFee + sumHotelFee + sumMealFee + sumOtherFee;
            const avgTrafficPerPerson = allTravelers.length > 0 ? Math.round((sumTrafficFee - sumTrafficBuffer) / allTravelers.length) : 0;
            const feeFormulas = {
                trafficFormula: `${allTravelers.length}人往返大交通基准 (¥${avgTrafficPerPerson.toLocaleString()}/人) + 改签弹性${Math.round(trafficBufferPercent * 100)}% (¥${sumTrafficBuffer.toLocaleString()}) = ¥${sumTrafficFee.toLocaleString()}`,
                hotelFormula: `${allTravelers.length}人住用合计 (${isTier1 ? '一线限额¥800/晚' : '二三线限额¥700/晚'}) = ¥${sumHotelFee.toLocaleString()}`,
                mealFormula: `${allTravelers.length}人差旅生活补贴 (往返乘车日各半额¥150，整天调研¥300) = ¥${sumMealFee.toLocaleString()}`,
                otherFormula: `${allTravelers.length}人市内出租/网约车预留Buffer (¥${cityBufferPerDay}/人/天) = ¥${sumOtherFee.toLocaleString()}`,
                totalFormula: `大交通 ¥${sumTrafficFee.toLocaleString()} + 酒店住宿 ¥${sumHotelFee.toLocaleString()} + 误餐补助 ¥${sumMealFee.toLocaleString()} + 市内Buffer ¥${sumOtherFee.toLocaleString()} = ¥${totalAmount.toLocaleString()}`
            };
            // 收集目的、调研地点与入住酒店
            const factories = Array.from(new Set(grp.map(g => g.targetFactories).filter(Boolean))).join('; ');
            const hotels = Array.from(new Set(grp.map(g => g.hotelName).filter(Boolean))).join('; ');
            const isMulti = allTravelers.length > 1;
            const purposeTag = isMulti ? `(含外驻人员合报)` : `(本人)`;
            const purpose = grp[0].purpose || `${destination}业务差旅与实地调研 ${purposeTag}`;
            // 主申请人（正社员）：规约明确要求报销人必须是当前登录的正社员，即便合报全为外驻人员出差，单据主报销人依然是该正社员
            const applicant = defaultMain || (allTravelers[0] || '当前用户');
            const isSelfTraveling = allTravelers.includes(applicant);
            const isProxy = !isSelfTraveling;
            const isCombined = allTravelers.length > 1 || isProxy;
            return {
                id: `TRIP-COMBINED-${tripNo}-${applicant}-${Math.random().toString(36).slice(2, 6)}`,
                tripNo,
                applicantName: applicant,
                isProxy,
                travelers: allTravelers,
                isCombined,
                startDate: minStartDate,
                endDate: maxEndDate,
                days: totalDays,
                nights: totalNights,
                destination,
                targetFactories: factories,
                hotelName: hotels,
                purpose,
                trafficFee: sumTrafficFee,
                hotelFee: sumHotelFee,
                mealFee: sumMealFee,
                otherFee: sumOtherFee,
                trafficBuffer: sumTrafficBuffer,
                totalAmount,
                legs: allLegs,
                feeFormulas,
                projectVO: grp[0].projectVO,
                projectName: grp[0].projectName,
                status: '就绪'
            };
        });
    }
    /**
     * 构造全量出差申请配置清单 (完全基于输入或现有状态动态计算，零硬编码)
     */
    function buildAllTripConfigurations(cityBufferPerDay = 100, trafficBufferPercent = 0.15, customInputs) {
        if (customInputs && customInputs.length > 0) {
            return customInputs.map((input, idx) => createDynamicTripConfig(input, cityBufferPerDay, trafficBufferPercent, idx + 1));
        }
        return [];
    }
    /**
     * 安全设置行级普通字段（若字段对象不存在则按元年元数据结构自适应创建，彻底杜绝 undefined.value 异常）
     */
    function ensureRowField(row, fieldName, value, dataType = 'STEXT', dataAttribute = 'DEFAULT') {
        if (!row.datas)
            row.datas = {};
        if (!row.datas[fieldName]) {
            row.datas[fieldName] = {
                dataAttribute,
                dataType,
                initValueType: '',
                style: '',
                value: value,
                valueCipher: ''
            };
        }
        else {
            row.datas[fieldName].value = value;
        }
    }
    /**
     * 安全设置行级金额字段（兼容 MONEY 结构，彻底杜绝 undefined.value.amount 异常）
     */
    function ensureRowMoneyField(row, fieldName, amount) {
        if (!row.datas)
            row.datas = {};
        if (!row.datas[fieldName]) {
            row.datas[fieldName] = {
                dataType: 'MONEY',
                initValueType: '',
                style: '',
                value: {
                    amount: amount,
                    capital: '',
                    exchangeRate: 1,
                    currencySymbol: '',
                    description: '',
                    currencyId: '6e589eb2dd9f11e8b5a69590a14a4e34',
                    factor: 0
                },
                valueCipher: ''
            };
        }
        else {
            if (!row.datas[fieldName].value || typeof row.datas[fieldName].value !== 'object') {
                row.datas[fieldName].value = {
                    amount: amount,
                    capital: '',
                    exchangeRate: 1,
                    currencySymbol: '',
                    description: '',
                    currencyId: '6e589eb2dd9f11e8b5a69590a14a4e34',
                    factor: 0
                };
            }
            else {
                row.datas[fieldName].value.amount = amount;
            }
        }
    }
    /**
     * 创建并持久化单张出差申请单草稿（通用生产入库）
     */
    async function createSingleTripApplicationApi(config, state) {
        try {
            // 1. 获取出行人人员对象 (动态维表解析)
            const applicantVO = await fetchPersonnelVO(config.applicantName, state);
            // 2. 初始化分配新单草稿与单号 (SC2609xxxx)
            const initRes = await apiRequest('/fssc/bill/billdata/getBillDataAndTemplateWrite', 'POST', {
                billDefineId: TRIP_CONSTANTS.billDefineId,
                appId: state.appId,
                scene: 'WRITE',
                applicantId: config.isProxy ? applicantVO.value : '',
                billMainId: ' ',
                source: 'PC'
            }, state);
            if (!initRes.success || !initRes.data || !initRes.data.billData) {
                throw new Error(initRes.message || '初始化出差申请草稿模板失败');
            }
            let billData = initRes.data.billData;
            const mainRow = billData.area.rowDatas[0];
            const billMainId = billData.billMainId;
            const billCode = mainRow.datas?.BILL_CODE?.value || billData.billCode || '';
            // 3. 代办/本人申请人绑定 (单据主申请人为正社员)
            if (mainRow.datas.APPLICANT_ID) {
                mainRow.datas.APPLICANT_ID.value = applicantVO;
            }
            else {
                ensureRowField(mainRow, 'APPLICANT_ID', applicantVO, 'PERSON');
            }
            if (mainRow.datas.USERS_ID) {
                mainRow.datas.USERS_ID.value = [applicantVO];
            }
            // 4. 回填主表基本信息与费用计算值 (含 Buffer，自适应创建字段，彻底免疫 undefined.value)
            const sDate = config.startDate.includes('T') ? config.startDate : `${config.startDate}T00:00`;
            const eDate = config.endDate.includes('T') ? config.endDate : `${config.endDate}T00:00`;
            ensureRowField(mainRow, 'START_TRIP_DATE', sDate, 'DATE');
            ensureRowField(mainRow, 'END_TRIP_DATE', eDate, 'DATE');
            ensureRowField(mainRow, 'F_CCLX', TRIP_CONSTANTS.cclx, 'RADIO');
            ensureRowField(mainRow, 'F_SQDJQF', TRIP_CONSTANTS.sqdjqf, 'RADIO');
            ensureRowField(mainRow, 'F_XMXG', TRIP_CONSTANTS.xmxg, 'RADIO');
            ensureRowField(mainRow, 'F_CZMDPU', config.purpose || '', 'MTEXT');
            const cleanCity = (config.destination || '').replace(/省|市|（.*）|\(.*\)/g, '').trim();
            ensureRowField(mainRow, 'F_CZXCIT', cleanCity, 'STEXT');
            let remaText = `预留市内交通Buffer: ¥${config.otherFee}; 改签Buffer: ¥${config.trafficBuffer}`;
            if (config.travelers && config.travelers.length > 1) {
                remaText = `合报出差人员: ${config.travelers.join('、')}; ` + remaText;
            }
            if (config.targetFactories) {
                remaText += `; 调研地点: ${config.targetFactories}`;
            }
            if (config.hotelName) {
                remaText += `; 入住酒店: ${config.hotelName}`;
            }
            ensureRowField(mainRow, 'F_BKREMA', remaText, 'STEXT');
            // 费用明细 (安全赋值，绝不抛 undefined.value 异常)
            ensureRowMoneyField(mainRow, 'F_HKYLJT', config.trafficFee);
            ensureRowMoneyField(mainRow, 'F_DHO', config.hotelFee);
            ensureRowMoneyField(mainRow, 'F_WCBZDI', config.mealFee);
            ensureRowMoneyField(mainRow, 'F_TOTH', config.otherFee);
            ensureRowMoneyField(mainRow, 'F_HJTOTA', config.totalAmount);
            ensureRowMoneyField(mainRow, 'BUDGET_SUM', config.totalAmount);
            // 5. 组装旅程明细区 (T_BILL_AREA_CCS_DEF_001)
            const tripAreaId = TRIP_CONSTANTS.tripDetailAreaId;
            const tripRowTpl = billData.areaTemplateRow?.[tripAreaId];
            let generatedLegRows = [];
            if (tripRowTpl && config.legs && config.legs.length > 0) {
                const cleanMain = (config.applicantName || '').replace(/（.*）|\(.*\)/g, '').trim();
                for (let i = 0; i < config.legs.length; i++) {
                    const leg = config.legs[i];
                    const fromCityVO = await fetchCityVO(leg.fromCity, state);
                    const toCityVO = await fetchCityVO(leg.toCity, state);
                    const row = JSON.parse(JSON.stringify(tripRowTpl));
                    const rowId = generateUuid();
                    row.rowId = rowId;
                    ensureRowField(row, 'ROW_NUM', i + 1, 'NUMBER');
                    ensureRowField(row, 'BILL_ROW_ID', rowId, 'STEXT');
                    ensureRowField(row, 'BILL_MAIN_ID', billMainId, 'STEXT');
                    ensureRowField(row, 'BILL_PARENT_ID', billMainId, 'STEXT');
                    ensureRowField(row, 'VERSION', 1, 'NUMBER');
                    ensureRowField(row, 'BILL_DEFINE_ID', TRIP_CONSTANTS.billDefineId, 'STEXT');
                    // 元年标准日期格式：2026-07-20T09:00 (长度 16，严禁带秒数，否则日期选择器无法识别导致显示为空)
                    let legDateStr = (leg.date || '').trim();
                    if (!legDateStr.includes('T')) {
                        legDateStr = `${legDateStr}T09:00`;
                    }
                    else if (legDateStr.length > 16) {
                        legDateStr = legDateStr.substring(0, 16);
                    }
                    ensureRowField(row, 'F_DATE', legDateStr, 'DATE');
                    ensureRowField(row, 'F_FROM', fromCityVO, 'DROPDOWN');
                    ensureRowField(row, 'F_TO', toCityVO, 'DROPDOWN');
                    // 核心规约与真实 HAR 规范：FLIGHT/TRAIN ETC. 字段中不仅填写班次，最后按规范标注出行人
                    // 真实填报格式：MU5227 | (陈浩) 或 MU5227 | (外驻:成勇)
                    let flightText = (leg.flightOrTrain || leg.transport || '飞机/高铁').trim();
                    const rawTraveler = (leg.travelerName || config.applicantName || '').trim();
                    const cleanTraveler = rawTraveler.replace(/（.*）|\(.*\)/g, '').trim();
                    const isExternal = cleanTraveler !== cleanMain && !cleanTraveler.includes(cleanMain);
                    const travelerLabel = isExternal ? `(外驻:${cleanTraveler})` : `(${cleanTraveler})`;
                    if (!flightText.includes(cleanTraveler)) {
                        flightText = `${flightText} | ${travelerLabel}`;
                    }
                    ensureRowField(row, 'F_FLIGHT', flightText, 'STEXT');
                    generatedLegRows.push(row);
                }
                if (mainRow.subAreaDatas) {
                    if (!mainRow.subAreaDatas[tripAreaId]) {
                        mainRow.subAreaDatas[tripAreaId] = {
                            boAreaCode: 'T_BILL_AREA_CCS_DEF_001',
                            boAreaId: tripAreaId,
                            rowDatas: []
                        };
                    }
                    mainRow.subAreaDatas[tripAreaId].rowDatas = generatedLegRows;
                }
            }
            // 6. 预算区蝴蝶效应联动 (DIM_ACCOUNT ➔ DIM_PROJECT)
            const budgetAreaId = TRIP_CONSTANTS.budgetAreaId;
            const budgetArea = mainRow.subAreaDatas?.[budgetAreaId];
            if (budgetArea && budgetArea.rowDatas && budgetArea.rowDatas.length > 0) {
                const bRow = budgetArea.rowDatas[0];
                const budgetRowId = bRow.rowId || bRow.datas?.BILL_ROW_ID?.value || '';
                // 项目联动 (动态项目维表绑定)
                let projectVO = config.projectVO;
                if (!projectVO && config.projectName) {
                    projectVO = await fetchProjectVO(config.projectName, state);
                }
                if (!projectVO && state.selectedProject) {
                    projectVO = {
                        value: state.selectedProject.value,
                        title: { zh_CN: state.selectedProject.title }
                    };
                }
                // 核心避坑：只有定位到合法 projectVO 时才联动为【项目预算】
                // 若未指定项目，则保留元年模板原有的合法科目（国内出張旅費），杜绝“项目必填”校验拦截
                if (projectVO) {
                    billData = await changeBillFieldValueApi('DIM_ACCOUNT', '科目', BUDGET_CONSTANTS.fields.account.fieldId, TRIP_CONSTANTS.account, budgetRowId, prepareBillSceneVO(billData), state);
                    billData = await changeBillFieldValueApi('DIM_PROJECT', '项目', BUDGET_CONSTANTS.fields.project.fieldId, projectVO, budgetRowId, prepareBillSceneVO(billData), state);
                }
                // 回填预算行客户负担与金额
                const updatedMainRow = billData.area.rowDatas[0];
                const updatedBRow = updatedMainRow.subAreaDatas?.[budgetAreaId]?.rowDatas?.[0];
                if (updatedBRow && updatedBRow.datas) {
                    if (updatedBRow.datas.F_KHFD)
                        updatedBRow.datas.F_KHFD.value = TRIP_CONSTANTS.khfd;
                    if (updatedBRow.datas.AMOUNT) {
                        if (!updatedBRow.datas.AMOUNT.value || typeof updatedBRow.datas.AMOUNT.value !== 'object') {
                            updatedBRow.datas.AMOUNT.value = { amount: config.totalAmount, exchangeRate: 1, currencyId: '6e589eb2dd9f11e8b5a69590a14a4e34', factor: 0 };
                        }
                        else {
                            updatedBRow.datas.AMOUNT.value.amount = config.totalAmount;
                        }
                        if (updatedBRow.datas.AMOUNT.value.accountAmount) {
                            updatedBRow.datas.AMOUNT.value.accountAmount.amount = config.totalAmount;
                        }
                    }
                    if (updatedBRow.datas.ACCOUNT_AMOUNT) {
                        if (!updatedBRow.datas.ACCOUNT_AMOUNT.value || typeof updatedBRow.datas.ACCOUNT_AMOUNT.value !== 'object') {
                            updatedBRow.datas.ACCOUNT_AMOUNT.value = { amount: config.totalAmount, exchangeRate: 1, currencyId: '6e589eb2dd9f11e8b5a69590a14a4e34', factor: 0 };
                        }
                        else {
                            updatedBRow.datas.ACCOUNT_AMOUNT.value.amount = config.totalAmount;
                        }
                    }
                }
                if (updatedMainRow.datas.BUDGET_SUM) {
                    ensureRowMoneyField(updatedMainRow, 'BUDGET_SUM', config.totalAmount);
                }
                if (updatedMainRow.datas.F_HJTOTA) {
                    ensureRowMoneyField(updatedMainRow, 'F_HJTOTA', config.totalAmount);
                }
            }
            // 确保旅程明细行完整持久化（防止被蝴蝶效应接口返回重置）
            if (generatedLegRows.length > 0) {
                const targetMainRow = billData.area.rowDatas[0];
                if (!targetMainRow.subAreaDatas)
                    targetMainRow.subAreaDatas = {};
                if (!targetMainRow.subAreaDatas[tripAreaId]) {
                    targetMainRow.subAreaDatas[tripAreaId] = {
                        boAreaCode: 'T_BILL_AREA_CCS_DEF_001',
                        boAreaId: tripAreaId,
                        rowDatas: []
                    };
                }
                targetMainRow.subAreaDatas[tripAreaId].rowDatas = generatedLegRows;
            }
            // 7. 持久化保存单据为草稿 (operationType: ADD, commit: false)
            const savePayload = JSON.parse(JSON.stringify(billData));
            savePayload.billButtons = [];
            savePayload.commit = false;
            savePayload.operationType = 'ADD';
            savePayload.scene = 'WRITE';
            savePayload.createNew = true;
            savePayload.dataModify = true;
            savePayload.allowSave = true;
            savePayload.statusEnum = 'UNCOMMITTED';
            if (!savePayload.attachmentDeleteList)
                savePayload.attachmentDeleteList = [];
            if (!savePayload.attachmentUploadList)
                savePayload.attachmentUploadList = [];
            if (savePayload.attachmentDeleteSync === undefined)
                savePayload.attachmentDeleteSync = false;
            const saveRes = await apiRequest('/fssc/bill/billdata/saveBillData', 'POST', savePayload, state);
            if (saveRes.success) {
                AutopilotLogger.info(`[DynamicTripApp] 成功创建出差申请草稿: ${billCode} (${config.applicantName} - ${config.destination})`);
                return {
                    success: true,
                    billCode: billCode,
                    billMainId: billMainId
                };
            }
            else {
                throw new Error(saveRes.message || '保存单据失败');
            }
        }
        catch (err) {
            AutopilotLogger.error(`[DynamicTripApp] 创建单据失败 [${config.applicantName} - ${config.destination}]: ${err.message}`);
            return {
                success: false,
                message: err.message || '未知错误'
            };
        }
    }

    function normalizeTime(t) {
        if (!t)
            return '';
        const clean = t.toString().trim();
        const parts = clean.split(':');
        if (parts.length >= 2) {
            return `${parts[0].trim().padStart(2, '0')}:${parts[1].trim().padStart(2, '0')}`;
        }
        return clean;
    }
    /**
     * 智能识别发票业务类别
     * 严禁将外部可变草稿参数 expenseTypeName 混入固有票面文本，避免循环自锁毒化
     */
    function detectInvoiceCategory(invVO = {}, rawItem = {}, expenseTypeName = '') {
        const seller = String(invVO.salesName || invVO.seller || rawItem.salesName || '').trim();
        const details = String(invVO.invoiceDetails || rawItem.invoiceDetails || '').trim();
        const goods = String(invVO.commodityNames || invVO.cargoInformation || invVO.goodsName || rawItem.goodsName || '').trim();
        const fileName = String(invVO.fileName || rawItem.fileName || '').trim();
        const abbr = String(invVO.invoiceTypeAbbreviation || rawItem.invoiceTypeAbbreviation || '').trim();
        const code = String(invVO.invoiceTypeCode || rawItem.invoiceTypeCode || '').trim();
        // 组合固有票面文本 (严禁混入 expenseTypeName)
        const intrinsicText = `${seller} ${details} ${goods} ${fileName} ${abbr}`.toLowerCase();
        // 1. 高速过路费/通行费判断 (如 "广州机场-酒店过路费.pdf"、"广东联合电子服务股份有限公司")
        const isToll = /过路费|通行费|高速|etc/.test(intrinsicText) ||
            /联合电子|高速公路|路桥|收费站/.test(seller);
        // 2. 出租车/网约车计程与乘车特征
        const hasRideMetadata = Boolean(isToll ||
            invVO.timeGetOn || rawItem.timeGetOn ||
            invVO.mileage || rawItem.mileage ||
            abbr === '出租车' || code === '10500' ||
            /出租车发票|出租汽车|网约车/.test(details) ||
            /出租汽车|滴滴|曹操|享道|t3|首汽|高德|美团打车/.test(seller));
        const amt = Number(rawItem.amount ?? rawItem.amt ?? rawItem.amountObj?.amount ?? invVO.amountTax ?? 0);
        // 3. 飞机票 (航空客票)
        if (/航空|机票|民航|航班|airline|flight|往返机票/.test(intrinsicText)) {
            return 'FLIGHT';
        }
        // 航司/旅行社电子行程单 (如 携程/华程西南 + 城市-城市往返路线，且无出租车计价器特征)
        const hasCityRoute = /[\u4e00-\u9fa5]{2,6}[-_至到➔][\u4e00-\u9fa5]{2,6}/.test(fileName);
        const isOTA = /旅行社|商旅|机票代理|携程|华程西南|同程|去哪儿|飞猪/.test(seller);
        if (isOTA && hasCityRoute && !hasRideMetadata) {
            return 'FLIGHT';
        }
        // 4. 火车票 (高铁/动车/列车客票)
        if (/铁路|12306|高铁|动车|火车站|列车|地铁/.test(intrinsicText) || abbr === '电-火车' || /铁路电子客票/.test(details)) {
            return 'TRAIN';
        }
        // 5. 酒店住宿 (需严格排除网约车/过路费特征)
        const hasHotelSeller = /酒店|宾馆|客栈|度假村|旅馆|会馆|饭店|旅社|民宿|hotel|inn/i.test(seller);
        const hasHotelFileName = /酒店|宾馆|住宿|客房|房费|hotel|inn|度假村/i.test(fileName) && !isToll && !/打车|出租车|车费|路桥费/.test(fileName);
        const hasHotelGoods = /住宿|客房|房费|住宿服务/.test(details) || /住宿|客房|房费|住宿服务/.test(goods);
        if (!hasRideMetadata && (hasHotelSeller || hasHotelFileName || hasHotelGoods)) {
            return 'HOTEL';
        }
        if (!hasRideMetadata && amt >= 280 && /酒店|住宿|客房/.test(intrinsicText)) {
            return 'HOTEL';
        }
        // 6. 通信费
        if (/移动|联通|电信|通信|手机|话费|telecom|unicom|mobile/i.test(intrinsicText) && !/手机终端|手机销售/.test(goods)) {
            return 'COMMUNICATION';
        }
        // 7. 会议与餐饮
        if (/会议|会务|会展/.test(intrinsicText)) {
            return 'MEETING';
        }
        if (/餐饮|餐馆|酒楼|食堂|饭庄|茶歇|美食/.test(intrinsicText)) {
            return 'ENTERTAINMENT_EXTERNAL';
        }
        // 8. 出租车 / 网约车 / 过路费
        if (hasRideMetadata || /出租车|网约车|滴滴|客运|出租汽车|曹操|t3|享道|首汽|高德|美团打车|打车|过路费|通行费/.test(intrinsicText)) {
            return 'TAXI';
        }
        // 9. 仅当固有票面无任何线索时，才参考既有的 expenseTypeName
        if (expenseTypeName) {
            const expLower = expenseTypeName.toLowerCase();
            if (/机|航/.test(expLower))
                return 'FLIGHT';
            if (/火车|高铁|动车/.test(expLower))
                return 'TRAIN';
            if (/住|宿|酒店|宾馆/.test(expLower))
                return 'HOTEL';
            if (/通|话费|移动/.test(expLower))
                return 'COMMUNICATION';
            if (/车|交通/.test(expLower))
                return 'TAXI';
        }
        // 10. 大额兜底安全线：单笔金额巨大 (> ¥350) 且无打车特征，绝不轻易归为出租车
        if (amt >= 350 && !hasRideMetadata) {
            if (/酒店|宾馆|宿/.test(intrinsicText))
                return 'HOTEL';
            if (/机票|航空|旅行社/.test(intrinsicText))
                return 'FLIGHT';
        }
        return 'OTHER';
    }
    /**
     * 纯动态通用交通枢纽与出发/到达站推断 (Zero Hardcoding 铁律)
     * 拒绝任何静态城市/机场字典硬编码，基于上下文票据文本动态提取，或依据交通方式与目的城市通用推导
     */
    function inferTripHub(dest, contextText = '') {
        const fn = (contextText || '');
        const cleanDest = (dest || '').trim().replace(/市|区|县/g, '');
        const isTrain = /高铁|动车|火车站|列车|铁路/.test(fn);
        const isFlight = /机票|航班|民航|航空|往返机票/.test(fn);
        let arrivalStation = '';
        // 1.1 显式到达站: 如 "-合肥南站", "到北京西站", "-嘉兴南站"
        const stationMatch = fn.match(/(?:到|至|[-_➔])\s*([^\s_（()）\-]{2,10}?(?:国际机场|机场|火车站|高铁站|东站|南站|西站|北站|客运站|站))/);
        if (stationMatch && stationMatch[1]) {
            arrivalStation = stationMatch[1].trim();
        }
        // 1.2 显式机场: 如 "上海虹桥-天津滨海机票", "大连周水子", "成都双流"
        if (!arrivalStation) {
            const airportDirectMatch = fn.match(/([^\s_（()）\-]{2,10}?(?:国际机场|机场))/);
            if (airportDirectMatch && airportDirectMatch[1] && !/上海|虹桥|浦东|北京首都/.test(airportDirectMatch[1])) {
                arrivalStation = airportDirectMatch[1].trim();
            }
            else {
                const flightHubMatch = fn.match(/(?:到|至|[-_➔])\s*([^\s_（()）\-]{2,8}?)(?:机票|航班|民航|往返机票)/);
                if (flightHubMatch && flightHubMatch[1]) {
                    const hubName = flightHubMatch[1].replace(/机票|往返|航班/g, '').trim();
                    if (hubName && !/上海|虹桥|浦东/.test(hubName)) {
                        arrivalStation = hubName.endsWith('机场') ? hubName : `${hubName}机场`;
                    }
                }
            }
        }
        // 1.3 显式高铁站: 如 "-嘉兴南高铁", "-合肥南"
        if (!arrivalStation && isTrain) {
            const trainHubMatch = fn.match(/(?:到|至|[-_➔])\s*([^\s_（()）\-]{2,8}?)(?:高铁|动车|列车|火车)/);
            if (trainHubMatch && trainHubMatch[1]) {
                const hubName = trainHubMatch[1].replace(/高铁|动车|列车|火车/g, '').trim();
                if (hubName && !/上海|虹桥/.test(hubName)) {
                    arrivalStation = hubName.endsWith('站') ? hubName : `${hubName}高铁站`;
                }
            }
        }
        // 2. 出发站 (动态从文件名或票据提取，若未提取到则采用通用占位模板)
        let departureStation = '出发地交通枢纽';
        const depMatch = fn.match(/([^\s_（()）\-]{2,10}?(?:国际机场|机场|火车站|高铁站|东站|南站|西站|北站|客运站|枢纽))(?:\s*[-_➔至到])/);
        if (depMatch && depMatch[1]) {
            const candidateDep = depMatch[1].trim();
            if (!cleanDest || !candidateDep.includes(cleanDest)) {
                departureStation = candidateDep;
            }
        }
        // 3. 通用兜底推导 (纯基于目的地名称与出行工具动态生成，绝不写死城市列表)
        if (!arrivalStation) {
            if (cleanDest) {
                arrivalStation = isTrain ? `${cleanDest}高铁站` : (isFlight ? `${cleanDest}机场` : `${cleanDest}交通枢纽`);
            }
            else {
                arrivalStation = isTrain ? '高铁站' : (isFlight ? '机场' : '交通枢纽');
            }
        }
        return {
            stationOrAirport: arrivalStation,
            departureStation,
            arrivalStation
        };
    }
    /**
     * 纯动态从票面/文件名中提取航线与车次起止站点路线 (Zero Hardcoding 铁律)
     */
    function extractRouteFromText(text) {
        if (!text)
            return null;
        const routeMatch = text.match(/([\u4e00-\u9fa5]{2,6})[-_至到➔]([\u4e00-\u9fa5]{2,6})/);
        if (routeMatch) {
            const c1 = routeMatch[1].replace(/^[0-9一二三四五六七八九十]+月[0-9]+[日号_]?/, '')
                .replace(/^[去到来回往乘坐]/, '')
                .replace(/机票|高铁|动车|列车|火车|市|酒店|往返|国际机场|机场|南站|西站|北站|东站|站/g, '').trim();
            const c2 = routeMatch[2].replace(/^[0-9一二三四五六七八九十]+月[0-9]+[日号_]?/, '')
                .replace(/^[去到来回往乘坐]/, '')
                .replace(/机票|高铁|动车|列车|火车|市|酒店|往返|国际机场|机场|南站|西站|北站|东站|站/g, '').trim();
            if (c1 && c2) {
                return { startCity: c1, endCity: c2, isRoute: true };
            }
        }
        return null;
    }
    /**
     * 纯动态从发票销售方/文件名提取酒店正规简称 (Zero Hardcoding 铁律)
     */
    function extractHotelName(salesName = '', fileName = '') {
        const fnClean = (fileName.replace(/\.pdf$/i, '').split('（')[0] || '').trim();
        const raw = fnClean || salesName || '';
        if (!raw)
            return '';
        const cleaned = raw.replace(/(?:管理)?(?:有限)?(?:责任)?公司.*$/, '')
            .replace(/^[0-9一二三四五六七八九十]+月[0-9]+[日号_]?/, '')
            .trim();
        return cleaned;
    }
    /**
     * 严格判定是否为高速公路通行费/过路费发票
     */
    function isTollInvoice(inv) {
        if (!inv)
            return false;
        const invVO = inv.invoiceVO || inv;
        const seller = String(invVO.salesName || invVO.seller || inv.salesName || '').trim();
        const details = String(invVO.invoiceDetails || inv.invoiceDetails || '').trim();
        const goods = String(invVO.commodityNames || invVO.cargoInformation || invVO.goodsName || inv.goodsName || '').trim();
        const fileName = String(invVO.fileName || inv.fileName || '').trim();
        const abbr = String(invVO.invoiceTypeAbbreviation || inv.invoiceTypeAbbreviation || '').trim();
        const text = `${seller} ${details} ${goods} ${fileName} ${abbr}`.toLowerCase();
        return /过路费|通行费|高速公路|路桥|收费公路|收费站|etc/.test(text) ||
            /联合电子|高速公路|路桥收费/.test(seller);
    }
    /**
     * 从 HH:mm 或 HH:mm:ss 字符串中解析全天分钟数 (0..1439)
     */
    function extractTimeInMinutes(timeStr) {
        if (!timeStr)
            return null;
        const m = String(timeStr).match(/(\d{1,2})[:：](\d{1,2})/);
        if (!m)
            return null;
        const hh = parseInt(m[1], 10);
        const mm = parseInt(m[2], 10);
        if (isNaN(hh) || isNaN(mm) || hh < 0 || hh > 23 || mm < 0 || mm > 59)
            return null;
        return hh * 60 + mm;
    }
    /**
     * 智能按时间窗口将过路费发票绑定合并到对应的出租车费用记录中（一笔费用多张发票）
     * 遵循 Anti-Hardcoding 铁律：基于客观时间差与地理枢纽特征通用对齐
     */
    function bindTollsToTaxiExpenses(invoices) {
        const bindingLog = [];
        let boundTollsCount = 0;
        // 1. 分离过路费与其它发票
        const tolls = [];
        const nonTolls = [];
        invoices.forEach(inv => {
            if (isTollInvoice(inv)) {
                tolls.push(inv);
            }
            else {
                nonTolls.push(inv);
            }
        });
        if (tolls.length === 0) {
            return { mergedItems: invoices, boundTollsCount: 0, bindingLog: [] };
        }
        // 2. 识别可被绑定的出租车/网约车行程 (type 为 TAXI 或 TRIP_TAXI，严格排除专票、酒店住宿、火车机票等非出租车票据)
        const taxis = nonTolls.filter(inv => {
            const text = `${inv.expenseTypeName || ''} ${inv.typeName || ''} ${inv.invoiceVO?.invoiceTypeAbbreviation || ''} ${inv.invoiceVO?.commodityNames || ''} ${inv.invoiceVO?.salesName || ''} ${inv.salesName || ''}`.toLowerCase();
            if (/专用发票|专票|增值税专用|增值税普通|普票|住宿|酒店|机票|航空|火车|高铁|动车/.test(text))
                return false;
            if ((Number(inv.amount) || 0) >= 350 && !/出租车|打车|网约车|滴滴/.test(text))
                return false;
            const cat = inv.type || detectInvoiceCategory(inv.invoiceVO || {}, inv, inv.expenseTypeName);
            return (cat === 'TAXI' || cat === 'TRIP_TAXI') && !isTollInvoice(inv);
        });
        // 3. 逐一为每张过路费寻找最佳出租车行程
        tolls.forEach(toll => {
            const tollDate = normalizeDate(toll.invoiceDate || (toll.invoiceVO && toll.invoiceVO.invoiceDate) || '');
            const tollAmt = Number(toll.amount ?? toll.invoiceVO?.amountTax ?? 0);
            // 尝试提取过路费的具体时间 (timeGetOn / invoiceTime / OCR / 文件名)
            const rawTollTime = toll.timeGetOn || toll.invoiceVO?.timeGetOn || toll.invoiceVO?.invoiceTime || toll.fileName || '';
            const tollMinutes = extractTimeInMinutes(rawTollTime);
            // 筛选同一天的出租车候选
            const sameDayTaxis = taxis.filter(t => normalizeDate(t.invoiceDate || '') === tollDate);
            let targetTaxi = null;
            if (sameDayTaxis.length === 1) {
                // 规则 1：同一天仅有一趟出租车，直接精准绑定
                targetTaxi = sameDayTaxis[0];
            }
            else if (sameDayTaxis.length > 1) {
                // 规则 2：同一天有多趟出租车
                if (tollMinutes !== null) {
                    // 2.1 优先寻找时间窗口包容的行程 (timeGetOn - 15min <= tollTime <= timeGetOff + 15min)
                    for (const taxi of sameDayTaxis) {
                        const startMin = extractTimeInMinutes(taxi.timeGetOn || '');
                        const endMin = extractTimeInMinutes(taxi.timeGetOff || '');
                        if (startMin !== null && endMin !== null) {
                            if (tollMinutes >= startMin - 15 && tollMinutes <= endMin + 15) {
                                targetTaxi = taxi;
                                break;
                            }
                        }
                        else if (startMin !== null) {
                            if (Math.abs(tollMinutes - startMin) <= 60) {
                                targetTaxi = taxi;
                                break;
                            }
                        }
                    }
                    // 2.2 若未完全包容，寻找时间距离最近的出租车行程
                    if (!targetTaxi) {
                        let minDiff = Infinity;
                        for (const taxi of sameDayTaxis) {
                            const startMin = extractTimeInMinutes(taxi.timeGetOn || '');
                            if (startMin !== null) {
                                const diff = Math.abs(tollMinutes - startMin);
                                if (diff < minDiff) {
                                    minDiff = diff;
                                    targetTaxi = taxi;
                                }
                            }
                        }
                    }
                }
                // 2.3 若无明确时间或未命中，依据语义线索（如文件名包含机场/高铁，且出租车前往机场）或大额/长途行程优先绑定
                if (!targetTaxi) {
                    const tollText = `${toll.fileName || ''} ${toll.invoiceVO?.fileName || ''} ${toll.salesName || ''}`;
                    const isAirportToll = /机场|民航|飞机场/.test(tollText);
                    const isStationToll = /高铁|火车站|车站/.test(tollText);
                    if (isAirportToll || isStationToll) {
                        targetTaxi = sameDayTaxis.find(t => {
                            const addr = `${t.startAddress || ''} ${t.endAddress || ''} ${t.description || ''}`;
                            return (isAirportToll && /机场/.test(addr)) || (isStationToll && /站|高铁/.test(addr));
                        }) || null;
                    }
                    // 2.4 仍未选出时，绑定到当天金额最高的那趟出租车（高速过路费通常伴随长距离高额行程）
                    if (!targetTaxi) {
                        const sorted = [...sameDayTaxis].sort((a, b) => (Number(b.amount || 0) - Number(a.amount || 0)));
                        targetTaxi = sorted[0];
                    }
                }
            }
            if (targetTaxi) {
                // 执行绑定
                targetTaxi.subInvoices = targetTaxi.subInvoices || [];
                targetTaxi.subInvoices.push(toll);
                targetTaxi.tollAmount = Number(((targetTaxi.tollAmount || 0) + tollAmt).toFixed(2));
                targetTaxi.amount = Number(((targetTaxi.amount || 0) + tollAmt).toFixed(2));
                targetTaxi.invoiceCount = 1 + targetTaxi.subInvoices.length;
                targetTaxi.isModified = true;
                toll.isMergedIntoOther = true;
                toll.parentExpenseRecordId = targetTaxi.expenseRecordId;
                boundTollsCount++;
                const descTollTag = `(含过路费¥${tollAmt})`;
                if (targetTaxi.description) {
                    if (!targetTaxi.description.includes('过路费')) {
                        targetTaxi.description = `${targetTaxi.description} ${descTollTag}`;
                    }
                }
                else {
                    targetTaxi.description = `市内交通 ${descTollTag}`;
                }
                bindingLog.push(`[${tollDate}] 过路费 ¥${tollAmt} (${toll.fileName || toll.salesName || '通行费'}) ➔ 绑定至出租车行程 ¥${targetTaxi.amount} (${targetTaxi.startAddress || ''}➔${targetTaxi.endAddress || ''})`);
            }
            else {
                // 孤立过路费（无任何出租车行程匹配）：安全保留为独立记录
                nonTolls.push(toll);
                bindingLog.push(`[${tollDate}] 过路费 ¥${tollAmt} 未找到同日出租车行程，保留为独立交通费记录`);
            }
        });
        return {
            mergedItems: nonTolls,
            boundTollsCount,
            bindingLog
        };
    }
    /**
     * 健壮的行程段数据归一化函数
     * 彻底容错不同大小写、下划线、缩写及嵌套属性名 (snake_case / camelCase / 中文 / legs)
     */
    function normalizeTripSegment(raw, defaultIndex = 1) {
        if (typeof raw === 'string') {
            const trimmed = raw.trim();
            if (trimmed.startsWith('{') && trimmed.endsWith('}')) {
                try {
                    raw = JSON.parse(trimmed);
                }
                catch {
                    // Not valid JSON
                }
            }
        }
        if (!raw || typeof raw !== 'object') {
            return {
                tripNo: defaultIndex,
                startDate: '',
                endDate: '',
                destination: '',
                hotelName: '',
                customerName: '',
                targetFactories: '',
                purpose: ''
            };
        }
        const tripNo = typeof raw.tripNo === 'number' ? raw.tripNo
            : (typeof raw.trip_no === 'number' ? raw.trip_no
                : (parseInt(String(raw.tripNo || raw.trip_no || raw.no || raw.index || raw['#'] || defaultIndex), 10) || defaultIndex));
        // 提取 startDate
        let rawStart = raw.startDate || raw.start_date || raw.beginDate || raw.begin_date || raw.start || raw.date || '';
        if (!rawStart && raw.timeRange && typeof raw.timeRange === 'string') {
            rawStart = raw.timeRange.split(/~|至|-/)[0]?.trim() || '';
        }
        if (!rawStart && Array.isArray(raw.dates) && raw.dates.length > 0) {
            rawStart = raw.dates[0];
        }
        if (!rawStart && Array.isArray(raw.legs) && raw.legs.length > 0) {
            rawStart = raw.legs[0].date;
        }
        // 提取 endDate
        let rawEnd = raw.endDate || raw.end_date || raw.finishDate || raw.finish_date || raw.end || '';
        if (!rawEnd && raw.timeRange && typeof raw.timeRange === 'string') {
            const parts = raw.timeRange.split(/~|至/);
            rawEnd = (parts.length > 1 ? parts[1] : parts[0])?.trim() || '';
        }
        if (!rawEnd && Array.isArray(raw.dates) && raw.dates.length > 0) {
            rawEnd = raw.dates[raw.dates.length - 1];
        }
        if (!rawEnd && Array.isArray(raw.legs) && raw.legs.length > 0) {
            rawEnd = raw.legs[raw.legs.length - 1].date;
        }
        if (!rawEnd && rawStart) {
            rawEnd = rawStart;
        }
        const startDate = normalizeDate(String(rawStart || '').trim());
        const endDate = normalizeDate(String(rawEnd || '').trim());
        // 提取 destination
        let dest = raw.destination || raw.dest || raw.city || raw.toCity || raw.targetCity || raw.to_city || '';
        if (!dest && Array.isArray(raw.legs) && raw.legs.length > 0) {
            dest = raw.legs[0].toCity || raw.legs[0].destination || '';
        }
        dest = String(dest || '').trim();
        // 提取 hotelName
        const hotel = String(raw.hotelName || raw.hotel_name || raw.hotel || raw.hotelTitle || '').trim();
        // 提取 targetFactories / customerName
        const factories = String(raw.targetFactories || raw.target_factories || raw.factory || raw.factories || '').trim();
        const customer = String(raw.customerName || raw.customer_name || raw.customer || raw.company || raw.client || factories || raw.purpose || '').trim();
        const purpose = String(raw.purpose || raw.reason || (factories ? `${dest}业务差旅与实地调研 (${factories})` : '')).trim();
        // 提取 stationOrAirport / departureStation / arrivalStation
        const rawStation = String(raw.stationOrAirport || raw.station_or_airport || raw.station || raw.airport || raw.hub || '').trim();
        const hubInfo = dest ? inferTripHub(dest, `${hotel} ${factories} ${customer} ${rawStation}`) : { stationOrAirport: '机场/高铁站', departureStation: '上海虹桥枢纽', arrivalStation: '机场/高铁站' };
        const departureStation = String(raw.departureStation || raw.departure_station || raw.depStation || hubInfo.departureStation).trim();
        const arrivalStation = String(raw.arrivalStation || raw.arrival_station || raw.arrStation || rawStation || hubInfo.arrivalStation).trim();
        const stationOrAirport = arrivalStation || rawStation || hubInfo.stationOrAirport;
        return {
            tripNo,
            startDate,
            endDate,
            destination: dest,
            hotelName: hotel,
            customerName: customer,
            targetFactories: factories || customer,
            stationOrAirport,
            departureStation,
            arrivalStation,
            purpose
        };
    }
    /**
     * 从全量发票池中智能自动反向聚类出差波次 (无需手动录入行程表)
     * 能够穿透发票附件名、大交通机票/高铁票、酒店住宿发票以及出租车日期跨度
     */
    function clusterTripsFromInvoices(invoices, options = {}) {
        if (!invoices || invoices.length === 0)
            return [];
        // 1. 过滤并排序具备有效日期的发票
        const datedInvoices = invoices
            .filter(inv => inv.invoiceDate && /^\d{4}-\d{2}-\d{2}$/.test(normalizeDate(inv.invoiceDate)))
            .map(inv => ({
            ...inv,
            normDate: normalizeDate(inv.invoiceDate || '')
        }))
            .sort((a, b) => a.normDate.localeCompare(b.normDate));
        if (datedInvoices.length === 0)
            return [];
        // 2. 辅助：纯动态从发票文本特征提取目的城市 (基于通用汉语地名结构与交通/酒店票据特征，拒绝静态城市字典)
        const getInvoiceCity = (inv) => {
            const text = `${inv.fileName || ''} ${inv.salesName || ''} ${inv.description || ''} ${inv.invoiceVO?.fileName || ''} ${inv.invoiceVO?.salesName || ''} ${inv.invoiceVO?.goodsName || ''}`;
            // 2.1 从大交通车票或往返行程文件名中动态提取目的地城市 (如 "8月21_天津_上海.pdf", "上海-大连_往返机票.pdf")
            const isTransportTicket = /机票|航班|民航|航空|高铁|动车|列车|火车|铁路/.test(text) ||
                (/旅行社|商旅|机票代理/.test(text) && /[-_至到➔]/.test(text));
            // 优先从航线/车次往返文件名提取 (如 "城市A-城市B" 或 "城市A_城市B")
            const fn = `${inv.fileName || ''} ${inv.invoiceVO?.fileName || ''}`;
            const routeMatch = fn.match(/([\u4e00-\u9fa5]{2,6})[-_至到➔]([\u4e00-\u9fa5]{2,6})/);
            if (routeMatch) {
                const clean1 = routeMatch[1].replace(/^[去到来回往乘坐]/, '').replace(/机票|高铁|动车|列车|火车|市|酒店|往返|国际机场|机场|南站|西站|北站|东站|站/g, '').trim();
                const clean2 = routeMatch[2].replace(/^[去到来回往乘坐]/, '').replace(/机票|高铁|动车|列车|火车|市|酒店|往返|国际机场|机场|南站|西站|北站|东站|站/g, '').trim();
                if (clean1 && !/上海|北京|虹桥|浦东/.test(clean1) && clean1.length >= 2)
                    return clean1;
                if (clean2 && !/上海|北京|虹桥|浦东/.test(clean2) && clean2.length >= 2)
                    return clean2;
            }
            if (isTransportTicket) {
                const ticketMatch = text.match(/(?:[-_➔至到]|到达|飞往|前往)\s*([\u4e00-\u9fa5]{2,8}?)(?:市|机票|高铁|动车|火车|航班|客票|往返|南站|西站|北站|东站|站|机场|_|\.|$)/);
                if (ticketMatch && ticketMatch[1]) {
                    let city = ticketMatch[1].replace(/^[去到来回往乘坐]/, '');
                    city = city.replace(/机票|高铁|酒店|往返|市|国际机场|机场|火车站|高铁站|东站|南站|西站|北站|客运站|航站楼|站/g, '').trim();
                    if (city.length > 2 && /[南北东西卫]$/.test(city)) {
                        city = city.slice(0, -1);
                    }
                    // 过滤常驻地/出发地/出发机场
                    if (city && !/上海|北京|虹桥|浦东/.test(city) && city.length >= 2) {
                        return city;
                    }
                }
            }
            // 2.2 从酒店发票中动态提取所在城市
            const hotelMatch = text.match(/(?:^|[^a-zA-Z\u4e00-\u9fa5])([\u4e00-\u9fa5]{2,4}?)(?:市|区|县|新区|开发区|经济技术开发区)?[^\s_（()）\-]{0,12}?(?:酒店|宾馆|客房|饭店|度假村|客栈|旅馆|会馆|旅社|民宿)/);
            if (hotelMatch && hotelMatch[1]) {
                let city = hotelMatch[1].replace(/^[去到来回往乘坐]/, '');
                city = city.replace(/有限公司|分公司|管理|集团|连锁/g, '').trim();
                if (city.length > 2 && /[南北东西]$/.test(city)) {
                    city = city.slice(0, -1);
                }
                if (city && !/上海|北京|虹桥|浦东/.test(city) && city.length >= 2) {
                    return city;
                }
                if (city === '金山')
                    return '金山';
            }
            // 2.3 宽松匹配 (必须带有交通/住宿特征)
            if (isTransportTicket || /酒店|住宿|客房|宾馆/.test(text)) {
                const looseMatch = text.match(/(?:上海|北京)?[-至_➔到]([\u4e00-\u9fa5]{2,4}?)(?:机票|高铁|酒店|往返|_)/);
                if (looseMatch && looseMatch[1]) {
                    const c = looseMatch[1].replace(/^[去到来回往乘坐]/, '').replace(/酒店|机票|高铁|市/g, '').trim();
                    if (c && !/上海|北京|虹桥|浦东/.test(c) && c.length >= 2)
                        return c;
                }
            }
            return '';
        };
        // 3. 智能多维聚类：结合日期跨度与目的城市跳跃
        const clusters = [];
        let currentCluster = [];
        const getClusterCity = (cluster) => {
            for (const it of cluster) {
                const c = getInvoiceCity(it);
                if (c)
                    return c;
            }
            return '';
        };
        for (let i = 0; i < datedInvoices.length; i++) {
            const item = datedInvoices[i];
            if (currentCluster.length === 0) {
                currentCluster.push(item);
            }
            else {
                const prevItem = currentCluster[currentCluster.length - 1];
                const prevTime = new Date(prevItem.normDate.replace(/-/g, '/')).getTime();
                const currTime = new Date(item.normDate.replace(/-/g, '/')).getTime();
                const startTime = new Date(currentCluster[0].normDate.replace(/-/g, '/')).getTime();
                const dayDiff = Math.round((currTime - prevTime) / (24 * 3600 * 1000));
                const totalSpan = Math.round((currTime - startTime) / (24 * 3600 * 1000));
                const itemCity = getInvoiceCity(item);
                const clusterCity = getClusterCity(currentCluster);
                let shouldSplit = false;
                if (itemCity && clusterCity && itemCity !== clusterCity) {
                    // 城市显式变化 (例如: 天津 ➔ 广州)
                    shouldSplit = true;
                }
                else if (dayDiff > 5) {
                    // 间隔超过 5 天，跨周必定为不同出差波次
                    shouldSplit = true;
                }
                else if (dayDiff > 2 && totalSpan > 6) {
                    // 本波次已满一周 (跨度 > 6天) 且出现跳跃
                    shouldSplit = true;
                }
                if (shouldSplit) {
                    clusters.push(currentCluster);
                    currentCluster = [item];
                }
                else {
                    currentCluster.push(item);
                }
            }
        }
        if (currentCluster.length > 0) {
            clusters.push(currentCluster);
        }
        // 4. 对每个波次智能提取城市、交通枢纽、酒店及客户据点
        const segments = [];
        clusters.forEach((group, idx) => {
            const startDate = group[0].normDate;
            const endDate = group[group.length - 1].normDate;
            // 收集该聚类下所有的线索文本 (文件名, 销售方, 描述, 备注)
            const allText = group.map(g => `${g.fileName || ''} ${g.salesName || ''} ${g.description || ''} ${g.invoiceVO?.fileName || ''} ${g.invoiceVO?.salesName || ''}`).join(' ');
            // 匹配目的城市
            let matchedCity = getClusterCity(group);
            // 如果未命中，尝试从组内线索文本总体提取
            if (!matchedCity) {
                matchedCity = getInvoiceCity({ fileName: allText });
            }
            if (!matchedCity) {
                matchedCity = `目的地${idx + 1}`;
            }
            // 提取酒店名称 (优先从真实的 HOTEL 发票提取酒店商号与品牌)
            let hotelName = '';
            // 1. 严格查找属于住宿/酒店类别的发票，严禁把出租车票当成酒店发票
            let hotelInv = group.find(g => {
                const cat = detectInvoiceCategory(g.invoiceVO || {}, g);
                return cat === 'HOTEL' || g.type === 'HOTEL';
            });
            if (!hotelInv) {
                hotelInv = group.find(g => {
                    const goods = g.invoiceVO?.goodsName || '';
                    const file = g.fileName || g.invoiceVO?.fileName || '';
                    return /住宿|客房|房费/.test(`${goods} ${file}`) && !/客运|出租车|打车|机票|火车/.test(`${goods} ${file}`);
                });
            }
            if (hotelInv) {
                const sales = (hotelInv.salesName || hotelInv.invoiceVO?.salesName || '').replace(/有限公司|分公司|管理|集团|连锁/g, '').trim();
                const file = (hotelInv.fileName || hotelInv.invoiceVO?.fileName || '').replace(/发票|住宿|（.*）|\(.*\)|.pdf|.ofd/g, '').trim();
                // 优先看 sales 和 file 是否包含酒店品牌
                const brandMatch = `${sales} ${file}`.match(/([^\s_（()）\-]+?(?:酒店|宾馆|客房|饭店|亚朵|全季|美悦|瑾程|上引))/);
                if (brandMatch) {
                    let candidate = brandMatch[1].replace(/有限公司|分公司|管理|市/g, '').trim();
                    if (!candidate.includes('到') && !candidate.includes('去') && !candidate.includes('车') && candidate.length >= 2) {
                        hotelName = candidate;
                    }
                }
                if (!hotelName && sales) {
                    hotelName = sales;
                }
            }
            // 次选：从文本中正则提取酒店名 (必须剔除带有行程指向的词汇)
            if (!hotelName) {
                const m = allText.match(/(?:入住|在|宿)?([^\s_（()）\-]{2,15}?(?:酒店|亚朵|全季|美悦|瑾程|上引))/);
                if (m && !m[1].includes('到') && !m[1].includes('去') && !m[1].includes('车')) {
                    hotelName = m[1].trim();
                }
            }
            if (!hotelName) {
                hotelName = `${matchedCity}商务酒店`;
            }
            // 标准化酒店名：若仅有品牌名则补齐“酒店”
            if (!hotelName.endsWith('酒店') && !hotelName.endsWith('宾馆') && !hotelName.endsWith('客房') && !hotelName.endsWith('饭店')) {
                hotelName += '酒店';
            }
            // 推断交通枢纽与客户据点 (严格遵循 Anti-Hardcoding 铁律，绝不硬编码或捏造私有客户工厂)
            const hubInfo = inferTripHub(matchedCity, allText);
            const globalCustomer = (options.customerName || '').trim();
            const customerName = globalCustomer;
            const factories = globalCustomer || `${matchedCity}客户据点`;
            segments.push({
                tripNo: idx + 1,
                startDate,
                endDate,
                destination: matchedCity,
                hotelName: hotelName || `${matchedCity}商务酒店`,
                customerName,
                targetFactories: factories,
                stationOrAirport: hubInfo.stationOrAirport,
                departureStation: hubInfo.departureStation,
                arrivalStation: hubInfo.arrivalStation,
                purpose: customerName ? `${matchedCity}业务差旅与实地调研 (${customerName})` : `${matchedCity}业务差旅与实地调研`
            });
        });
        return segments;
    }
    /**
     * 通用多模式智能费用规划与行程推断引擎
     *
     * 覆盖场景：
     * 1. 异地出差模式 (Business Trip Routine)：
     *    - 出发日：公司/家 ➔ 机场/高铁站 (送机送站) ➔ 飞机/高铁 ➔ 机场/高铁站 ➔ 酒店/客户
     *    - 中间调研日：早出晚归 酒店 ➔ 客户 (早) / 客户 ➔ 酒店 (晚)
     *    - 返程日：酒店 ➔ 机场/高铁站 ➔ 飞机/高铁 ➔ 机场/高铁站 ➔ 家/公司
     * 2. 市内日常拜访模式 (Local Commute Routine)：
     *    - 当天第1程：公司 ➔ 客户；当天第2程：客户 ➔ 公司
     * 3. 代外驻报销规范：
     *    - 费用说明自动标准化生成：`[外驻:姓名] 项目号 客户名`
     */
    function inferSmartExpensePlan(invoices, options = {}) {
        const company = (options.companyName || 'IVISION').trim();
        const customer = (options.customerName || '').trim();
        const hotel = (options.hotelName || '').trim();
        const station = (options.stationOrAirport || '机场/高铁站').trim();
        const home = (options.homeName || '家').trim();
        const project = (options.projectName || '').trim();
        const proxyPerson = (options.proxyPersonName || '').trim();
        const customDesc = (options.customDescription || '').trim();
        const departureDate = options.departureDate ? normalizeDate(options.departureDate) : '';
        const returnDate = options.returnDate ? normalizeDate(options.returnDate) : '';
        // 解析多波次行程计划 (表格文本或结构化 trips，全量统一归一化)
        let tripSegments = [];
        if (options.trips && options.trips.length > 0) {
            const rawSegments = options.trips.map((t, idx) => normalizeTripSegment(t, idx + 1));
            // 过滤空波次占位符 (防止历史残留的无日期、无目的地的空 trip 污染阻断自动聚类)
            tripSegments = rawSegments.filter(s => Boolean((s.destination && !s.destination.includes('待定')) || s.startDate || s.endDate));
        }
        else if (options.itineraryText) {
            try {
                const parsed = parseItineraryTable(options.itineraryText);
                tripSegments = parsed.map((item, idx) => normalizeTripSegment(item, idx + 1));
            }
            catch (e) {
                console.warn('[commuteService] parseItineraryTable error:', e);
            }
        }
        // 若依然未提供有效行程表（或传入的全是空占位符），系统纯自动根据发票中的机票/高铁票/酒店发票智能聚类
        if (tripSegments.length === 0 && invoices && invoices.length > 0) {
            tripSegments = clusterTripsFromInvoices(invoices, options);
        }
        // 辅助：查找指定日期所属的出差波次 (优先精确包含，容差前后1-3天)
        const findMatchingTrip = (dateStr) => {
            if (!dateStr || tripSegments.length === 0)
                return undefined;
            // 优先区间匹配 (含起止日)
            const exact = tripSegments.find(s => s.startDate && s.endDate && dateStr >= s.startDate && dateStr <= s.endDate);
            if (exact)
                return exact;
            const invTime = new Date(dateStr.replace(/-/g, '/')).getTime();
            if (isNaN(invTime))
                return undefined;
            let closest = undefined;
            let minDiff = Infinity;
            for (const s of tripSegments) {
                if (!s.startDate || !s.endDate)
                    continue;
                const sTime = new Date(s.startDate.replace(/-/g, '/')).getTime();
                const eTime = new Date(s.endDate.replace(/-/g, '/')).getTime();
                if (isNaN(sTime) || isNaN(eTime))
                    continue;
                if (invTime >= sTime - 24 * 3600 * 1000 && invTime <= eTime + 24 * 3600 * 1000) {
                    return s;
                }
                const diff = Math.min(Math.abs(invTime - sTime), Math.abs(invTime - eTime));
                if (diff < minDiff) {
                    minDiff = diff;
                    closest = s;
                }
            }
            return (minDiff <= 3 * 24 * 3600 * 1000) ? closest : undefined;
        };
        // 判断出差模式还是市内模式
        let tripType = 'LOCAL_COMMUTE';
        if (tripSegments.length > 0 || options.tripType === 'BUSINESS_TRIP') {
            tripType = 'BUSINESS_TRIP';
        }
        else if (options.tripType === 'COMMUNICATION_ONLY') {
            tripType = 'COMMUNICATION_ONLY';
        }
        else if (options.tripType === 'AUTO' || !options.tripType) {
            const hasHotelOrFlight = invoices.some(inv => {
                const cat = detectInvoiceCategory(inv.invoiceVO || {}, inv, inv.expenseTypeName || '');
                return cat === 'HOTEL' || cat === 'FLIGHT' || cat === 'TRAIN';
            });
            if (hasHotelOrFlight || hotel || (departureDate && returnDate && departureDate !== returnDate)) {
                tripType = 'BUSINESS_TRIP';
            }
            else {
                tripType = 'LOCAL_COMMUTE';
            }
        }
        // 检查缺失的关键字段：遵循通用性原则，如客户名称未明确，绝不自作主张捏造，加入 missingFields 让 A2UI 表单交互给用户输入！
        const missingFields = [];
        if (!customer && tripSegments.every(t => !t.customerName)) {
            missingFields.push('拜访客户名称 (customerName)');
        }
        if (tripSegments.length === 0) {
            if (tripType === 'BUSINESS_TRIP' && !hotel) {
                const hasHotelInv = invoices.some(i => detectInvoiceCategory(i.invoiceVO || {}, i) === 'HOTEL');
                if (!hasHotelInv)
                    missingFields.push('入住酒店名称 (hotelName)');
            }
        }
        // 目标索引过滤
        const targetSet = options.recordIndices && options.recordIndices.length > 0
            ? new Set(options.recordIndices)
            : new Set(invoices.map((_, idx) => idx));
        // 按日期分组出租车
        const taxiDateGroups = {};
        const uncertainDates = [];
        let modifiedCount = 0;
        // 格式化生成标准费用说明
        const buildDescription = (baseTypeDesc = '', custOverride) => {
            if (customDesc)
                return customDesc;
            const parts = [];
            if (proxyPerson) {
                parts.push(`[外驻:${proxyPerson}]`);
            }
            if (project) {
                parts.push(project);
            }
            const activeCustomer = custOverride || customer;
            if (activeCustomer) {
                parts.push(activeCustomer);
            }
            if (baseTypeDesc && !project && !activeCustomer) {
                parts.push(baseTypeDesc);
            }
            return parts.join(' ').trim();
        };
        invoices.forEach((inv, idx) => {
            if (!targetSet.has(idx))
                return;
            // 识别发票分类
            const detectedCat = detectInvoiceCategory(inv.invoiceVO || {}, inv, inv.expenseTypeName || '');
            const invDate = normalizeDate(inv.invoiceDate || '');
            const matchedTrip = findMatchingTrip(invDate);
            const rowHotel = (matchedTrip && matchedTrip.hotelName) || hotel;
            const rowCustomer = (matchedTrip && (matchedTrip.customerName || matchedTrip.targetFactories)) || customer;
            const rowDest = (matchedTrip && matchedTrip.destination) || '';
            // 绑定项目与代外驻人名
            if (project)
                inv.projectName = project;
            if (proxyPerson)
                inv.proxyPersonName = proxyPerson;
            if (rowHotel)
                inv.hotelName = rowHotel;
            if (station)
                inv.stationOrAirport = station;
            // 分类处理
            if (detectedCat === 'FLIGHT') {
                inv.type = 'FLIGHT';
                inv.expenseTypeId = EXPENSE_TYPES.FLIGHT.id;
                inv.expenseTypeName = EXPENSE_TYPES.FLIGHT.name;
                inv.expenseTypeCode = EXPENSE_TYPES.FLIGHT.code;
                const route = extractRouteFromText(`${inv.fileName || ''} ${inv.invoiceVO?.fileName || ''}`);
                const flightStart = route ? route.startCity : (company || '上海');
                const flightEnd = route ? route.endCity : (rowDest || '外地目的地');
                const isRoundTrip = /往返/.test(`${inv.fileName || ''} ${inv.invoiceVO?.fileName || ''}`);
                const flightDest = (flightEnd !== '上海' && flightEnd !== '北京') ? flightEnd : flightStart;
                inv.description = buildDescription(`${flightDest ? `${flightDest}` : ''}${isRoundTrip ? '往返机票' : '机票'}`, rowCustomer);
                inv.isBusinessTrip = true;
                inv.startAddress = flightStart;
                inv.endAddress = flightEnd;
                inv.isModified = true;
                modifiedCount++;
            }
            else if (detectedCat === 'TRAIN') {
                inv.type = 'TRAIN';
                inv.expenseTypeId = EXPENSE_TYPES.TRAIN.id;
                inv.expenseTypeName = EXPENSE_TYPES.TRAIN.name;
                inv.expenseTypeCode = EXPENSE_TYPES.TRAIN.code;
                const route = extractRouteFromText(`${inv.fileName || ''} ${inv.invoiceVO?.fileName || ''}`);
                const trainStart = route ? route.startCity : (company || '上海');
                const trainEnd = route ? route.endCity : (rowDest || '外地目的地');
                const trainDest = (trainEnd !== '上海' && trainEnd !== '北京') ? trainEnd : trainStart;
                inv.description = buildDescription(`${trainDest ? `${trainDest}` : ''}火车/高铁票`, rowCustomer);
                inv.isBusinessTrip = true;
                inv.startAddress = trainStart;
                inv.endAddress = trainEnd;
                inv.isModified = true;
                modifiedCount++;
            }
            else if (detectedCat === 'HOTEL') {
                inv.type = 'HOTEL';
                inv.expenseTypeId = EXPENSE_TYPES.HOTEL.id;
                inv.expenseTypeName = EXPENSE_TYPES.HOTEL.name;
                inv.expenseTypeCode = EXPENSE_TYPES.HOTEL.code;
                const extractedHotel = extractHotelName(inv.salesName || inv.invoiceVO?.salesName || '', inv.fileName || inv.invoiceVO?.fileName || '');
                const finalHotel = extractedHotel || rowHotel || '出差酒店';
                // 城市推断高优先级：首先锚定当前出差波次的真实目的城市 (destination / destCity)
                let derivedCity = matchedTrip?.destCity || matchedTrip?.destination || rowDest || '';
                if (!derivedCity && finalHotel) {
                    // 容灾提取：从酒店名称中提取真实城市（如“亚朵酒店（合肥滨湖店）”提取“合肥”）
                    const innerMatch = finalHotel.match(/[（(]([\u4e00-\u9fa5]{2,3}?)(?:市|区|镇|县|店|新区|经开区|[\u4e00-\u9fa5]*?店)/);
                    if (innerMatch && !/金山|中山|国家|滨湖|云谷|金融|台山|白山|会展/.test(innerMatch[1])) {
                        derivedCity = innerMatch[1];
                    }
                    else {
                        const prefixMatch = finalHotel.match(/^([\u4e00-\u9fa5]{2,3}?)(?:市|酒店|宾馆|饭店|客栈)/);
                        if (prefixMatch && !/亚朵|全季|上引|如家|汉庭|锦江|美悦|希尔|万豪|洲际|格林|维也|桔子|宜必|凯悦|喜来|香格/.test(prefixMatch[1])) {
                            derivedCity = prefixMatch[1];
                        }
                    }
                }
                const hotelCity = (derivedCity || '出差城市').replace(/市|（.*）|\(.*\)/g, '').trim();
                inv.hotelName = finalHotel;
                inv.description = buildDescription(`${finalHotel}住宿`, rowCustomer);
                inv.isBusinessTrip = true;
                inv.startAddress = hotelCity;
                inv.endAddress = finalHotel;
                inv.city = hotelCity;
                // 智能对齐入住/离店日期与住店天数
                if (matchedTrip) {
                    inv.checkInDate = matchedTrip.startDate || invDate;
                    inv.checkOutDate = matchedTrip.endDate || invDate;
                }
                else {
                    inv.checkInDate = invDate;
                    inv.checkOutDate = invDate;
                }
                let stayDays = 1;
                if (inv.checkInDate && inv.checkOutDate) {
                    const d1 = new Date(inv.checkInDate).getTime();
                    const d2 = new Date(inv.checkOutDate).getTime();
                    const diffDays = Math.round((d2 - d1) / (1000 * 60 * 60 * 24));
                    if (diffDays > 0)
                        stayDays = diffDays;
                }
                inv.stayDays = stayDays;
                inv.isModified = true;
                modifiedCount++;
            }
            else if (detectedCat === 'COMMUNICATION') {
                inv.type = 'COMMUNICATION';
                inv.expenseTypeId = EXPENSE_TYPES.COMMUNICATION.id;
                inv.expenseTypeName = EXPENSE_TYPES.COMMUNICATION.name;
                inv.expenseTypeCode = EXPENSE_TYPES.COMMUNICATION.code;
                inv.description = buildDescription('手机通讯费', rowCustomer);
                inv.isModified = true;
                modifiedCount++;
            }
            else if (detectedCat === 'OTHER' && (Number(inv.amount) || 0) >= 350 && !/出租车|打车|网约车|滴滴/.test(`${inv.salesName || ''} ${inv.fileName || ''} ${inv.expenseTypeName || ''}`)) {
                // 大额非打车发票（如酒店住宿兜底，严禁降级为出租车）
                inv.type = 'HOTEL';
                inv.expenseTypeId = EXPENSE_TYPES.HOTEL.id;
                inv.expenseTypeName = EXPENSE_TYPES.HOTEL.name;
                inv.expenseTypeCode = EXPENSE_TYPES.HOTEL.code;
                inv.isBusinessTrip = true;
                inv.description = buildDescription('差旅住宿费', rowCustomer);
                inv.isModified = true;
                modifiedCount++;
            }
            else {
                // 出租车/交通费
                const isTrip = tripType === 'BUSINESS_TRIP';
                inv.type = isTrip ? 'TRIP_TAXI' : 'TAXI';
                inv.expenseTypeId = isTrip ? EXPENSE_TYPES.TRIP_TAXI.id : EXPENSE_TYPES.TAXI.id;
                inv.expenseTypeName = isTrip ? EXPENSE_TYPES.TRIP_TAXI.name : EXPENSE_TYPES.TAXI.name;
                inv.expenseTypeCode = isTrip ? EXPENSE_TYPES.TRIP_TAXI.code : EXPENSE_TYPES.TAXI.code;
                inv.isBusinessTrip = isTrip;
                const dt = invDate || '未知日期';
                if (!taxiDateGroups[dt])
                    taxiDateGroups[dt] = [];
                taxiDateGroups[dt].push(idx);
            }
        });
        // 推断出租车行程 (出发地 / 到达地 / 费用说明)
        Object.keys(taxiDateGroups).forEach(dt => {
            const indicesInDate = taxiDateGroups[dt];
            indicesInDate.sort((a, b) => {
                const timeA = normalizeTime(invoices[a].timeGetOn) || '00:00';
                const timeB = normalizeTime(invoices[b].timeGetOn) || '00:00';
                return timeA.localeCompare(timeB);
            });
            const matchedTrip = findMatchingTrip(dt);
            const isDepDay = Boolean((departureDate && dt === departureDate) || (matchedTrip && dt === matchedTrip.startDate));
            const isRetDay = Boolean((returnDate && dt === returnDate) || (matchedTrip && dt === matchedTrip.endDate));
            const targetHotel = (matchedTrip && matchedTrip.hotelName) || hotel || '出差酒店';
            const targetCustomer = (matchedTrip && (matchedTrip.customerName || matchedTrip.targetFactories)) || customer || '客户据点';
            // 区分出发地枢纽 (默认上海虹桥) 与 目的地交通枢纽 (如滨海国际机场/白云机场/合肥南站等)
            const targetDepStation = (matchedTrip && matchedTrip.departureStation) || '上海虹桥枢纽';
            const targetArrStation = (matchedTrip && (matchedTrip.arrivalStation || matchedTrip.stationOrAirport)) || (station !== '机场/高铁站' ? station : '目的地机场/高铁站');
            if (tripType === 'BUSINESS_TRIP') {
                // =====================================
                // 模式 1: 异地出差行程推断
                // =====================================
                if (isDepDay) {
                    // 出发日
                    if (indicesInDate.length === 1) {
                        // 仅有1程：送机/送站
                        const row = invoices[indicesInDate[0]];
                        row.startAddress = company || home;
                        row.endAddress = targetDepStation;
                        row.description = buildDescription(`出发去${targetDepStation}`, targetCustomer);
                        row.isModified = true;
                        modifiedCount++;
                    }
                    else if (indicesInDate.length === 2) {
                        // 第1程：出发城市送机/送站；第2程：到达目的地机场/高铁站后接机去酒店或客户工厂
                        const row1 = invoices[indicesInDate[0]];
                        row1.startAddress = company || home;
                        row1.endAddress = targetDepStation;
                        row1.description = buildDescription(`出发去${targetDepStation}`, targetCustomer);
                        row1.isModified = true;
                        const row2 = invoices[indicesInDate[1]];
                        row2.startAddress = targetArrStation;
                        row2.endAddress = targetHotel;
                        row2.description = buildDescription(`到达去${targetHotel}`, targetCustomer);
                        row2.isModified = true;
                        modifiedCount += 2;
                    }
                    else {
                        // 出发日 3 程及以上 (如：去机场 -> 到达去客户工厂 -> 晚上回酒店)
                        const row1 = invoices[indicesInDate[0]];
                        row1.startAddress = company || home;
                        row1.endAddress = targetDepStation;
                        row1.description = buildDescription(`出发去${targetDepStation}`, targetCustomer);
                        row1.isModified = true;
                        const row2 = invoices[indicesInDate[1]];
                        row2.startAddress = targetArrStation;
                        row2.endAddress = targetCustomer;
                        row2.description = buildDescription(`到达去${targetCustomer}`, targetCustomer);
                        row2.isModified = true;
                        const rowLast = invoices[indicesInDate[indicesInDate.length - 1]];
                        rowLast.startAddress = targetCustomer;
                        rowLast.endAddress = targetHotel;
                        rowLast.description = buildDescription(`调研结束回${targetHotel}`, targetCustomer);
                        rowLast.isModified = true;
                        for (let k = 2; k < indicesInDate.length - 1; k++) {
                            const midRow = invoices[indicesInDate[k]];
                            midRow.startAddress = targetHotel;
                            midRow.endAddress = targetCustomer;
                            midRow.description = buildDescription('出差市内交通', targetCustomer);
                            midRow.isModified = true;
                        }
                        modifiedCount += indicesInDate.length;
                        uncertainDates.push(`${dt} (出发日多程)`);
                    }
                }
                else if (isRetDay) {
                    // 返程日
                    if (indicesInDate.length === 1) {
                        const row = invoices[indicesInDate[0]];
                        const hour = parseInt((normalizeTime(row.timeGetOn).split(':')[0] || '12'), 10);
                        if (hour >= 17) {
                            row.startAddress = targetDepStation;
                            row.endAddress = home || company;
                            row.description = buildDescription(`返程到达${targetDepStation}回家`, targetCustomer);
                        }
                        else {
                            row.startAddress = targetHotel;
                            row.endAddress = targetArrStation;
                            row.description = buildDescription(`返程去${targetArrStation}`, targetCustomer);
                        }
                        row.isModified = true;
                        modifiedCount++;
                    }
                    else if (indicesInDate.length === 2) {
                        const row1 = invoices[indicesInDate[0]];
                        row1.startAddress = targetHotel;
                        row1.endAddress = targetArrStation;
                        row1.description = buildDescription(`返程去${targetArrStation}`, targetCustomer);
                        row1.isModified = true;
                        const row2 = invoices[indicesInDate[1]];
                        row2.startAddress = targetDepStation;
                        row2.endAddress = home || company;
                        row2.description = buildDescription(`返程到达${targetDepStation}回家`, targetCustomer);
                        row2.isModified = true;
                        modifiedCount += 2;
                    }
                    else {
                        // 返程日 3 程及以上 (早程去客户 -> 客户去机场/车站 -> 回到上海去家)
                        const row1 = invoices[indicesInDate[0]];
                        row1.startAddress = targetHotel;
                        row1.endAddress = targetCustomer;
                        row1.description = buildDescription('上午调研拜访', targetCustomer);
                        row1.isModified = true;
                        const rowPenultimate = invoices[indicesInDate[indicesInDate.length - 2]];
                        rowPenultimate.startAddress = targetCustomer;
                        rowPenultimate.endAddress = targetArrStation;
                        rowPenultimate.description = buildDescription(`返程去${targetArrStation}`, targetCustomer);
                        rowPenultimate.isModified = true;
                        const rowLast = invoices[indicesInDate[indicesInDate.length - 1]];
                        rowLast.startAddress = targetDepStation;
                        rowLast.endAddress = home || company;
                        rowLast.description = buildDescription(`返程到达${targetDepStation}回家`, targetCustomer);
                        rowLast.isModified = true;
                        for (let k = 1; k < indicesInDate.length - 2; k++) {
                            const midRow = invoices[indicesInDate[k]];
                            midRow.startAddress = targetCustomer;
                            midRow.endAddress = targetCustomer;
                            midRow.description = buildDescription('出差市内交通', targetCustomer);
                            midRow.isModified = true;
                        }
                        modifiedCount += indicesInDate.length;
                        uncertainDates.push(`${dt} (返程日多程)`);
                    }
                }
                else {
                    // 中间调研日 (早出晚归: 酒店 ➔ 客户 / 客户 ➔ 酒店)
                    if (indicesInDate.length === 1) {
                        const row = invoices[indicesInDate[0]];
                        const hour = parseInt((normalizeTime(row.timeGetOn).split(':')[0] || '12'), 10);
                        if (hour < 14) {
                            row.startAddress = targetHotel;
                            row.endAddress = targetCustomer;
                            row.description = buildDescription('出差早程调研', targetCustomer);
                        }
                        else {
                            row.startAddress = targetCustomer;
                            row.endAddress = targetHotel;
                            row.description = buildDescription('出差晚程回酒店', targetCustomer);
                        }
                        row.isModified = true;
                        modifiedCount++;
                    }
                    else if (indicesInDate.length === 2) {
                        const row1 = invoices[indicesInDate[0]];
                        row1.startAddress = targetHotel;
                        row1.endAddress = targetCustomer;
                        row1.description = buildDescription('出差早程调研', targetCustomer);
                        row1.isModified = true;
                        const row2 = invoices[indicesInDate[1]];
                        row2.startAddress = targetCustomer;
                        row2.endAddress = targetHotel;
                        row2.description = buildDescription('出差晚程回酒店', targetCustomer);
                        row2.isModified = true;
                        modifiedCount += 2;
                    }
                    else {
                        const row1 = invoices[indicesInDate[0]];
                        row1.startAddress = targetHotel;
                        row1.endAddress = targetCustomer;
                        row1.description = buildDescription('出差早程调研', targetCustomer);
                        row1.isModified = true;
                        const rowLast = invoices[indicesInDate[indicesInDate.length - 1]];
                        rowLast.startAddress = targetCustomer;
                        rowLast.endAddress = targetHotel;
                        rowLast.description = buildDescription('出差晚程回酒店', targetCustomer);
                        rowLast.isModified = true;
                        for (let k = 1; k < indicesInDate.length - 1; k++) {
                            const midRow = invoices[indicesInDate[k]];
                            midRow.startAddress = targetCustomer;
                            midRow.endAddress = targetCustomer;
                            midRow.description = buildDescription('客户据点间交通', targetCustomer);
                            midRow.isModified = true;
                        }
                        modifiedCount += indicesInDate.length;
                        uncertainDates.push(`${dt} (多程调研)`);
                    }
                }
            }
            else {
                // =====================================
                // 模式 2: 市内日常拜访推断 (公司 ⇄ 客户)
                // =====================================
                if (indicesInDate.length === 1) {
                    const row = invoices[indicesInDate[0]];
                    const hour = parseInt((normalizeTime(row.timeGetOn).split(':')[0] || '12'), 10);
                    if (hour < 14) {
                        row.startAddress = company;
                        row.endAddress = customer;
                    }
                    else {
                        row.startAddress = customer;
                        row.endAddress = company;
                    }
                    row.description = buildDescription('市内拜访客户');
                    row.isModified = true;
                    modifiedCount++;
                }
                else if (indicesInDate.length === 2) {
                    const row1 = invoices[indicesInDate[0]];
                    row1.startAddress = company;
                    row1.endAddress = customer;
                    row1.description = buildDescription('上午出发拜访客户');
                    row1.isModified = true;
                    const row2 = invoices[indicesInDate[1]];
                    row2.startAddress = customer;
                    row2.endAddress = company;
                    row2.description = buildDescription('下午返回公司');
                    row2.isModified = true;
                    modifiedCount += 2;
                }
                else {
                    const row1 = invoices[indicesInDate[0]];
                    row1.startAddress = company;
                    row1.endAddress = customer;
                    row1.description = buildDescription('上午出发拜访客户');
                    row1.isModified = true;
                    const rowLast = invoices[indicesInDate[indicesInDate.length - 1]];
                    rowLast.startAddress = customer;
                    rowLast.endAddress = company;
                    rowLast.description = buildDescription('下午返回公司');
                    rowLast.isModified = true;
                    for (let k = 1; k < indicesInDate.length - 1; k++) {
                        const midRow = invoices[indicesInDate[k]];
                        midRow.startAddress = customer;
                        midRow.endAddress = customer;
                        midRow.description = buildDescription('市内网约车');
                        midRow.isModified = true;
                    }
                    modifiedCount += indicesInDate.length;
                    uncertainDates.push(`${dt} (${indicesInDate.length} 笔)`);
                }
            }
        });
        // 动态检测是否存在同期的出租车与过路费发票（遵循 Anti-Hardcoding 铁律，基于通用类型与日期对齐）
        const concurrentTolls = invoices.filter(inv => {
            if (!isTollInvoice(inv))
                return false;
            const tollDate = normalizeDate(inv.invoiceDate || (inv.invoiceVO && inv.invoiceVO.invoiceDate) || '');
            return invoices.some(t => !isTollInvoice(t) && (t.type === 'TAXI' || t.type === 'TRIP_TAXI') && normalizeDate(t.invoiceDate || '') === tollDate);
        });
        const hasConcurrentTolls = concurrentTolls.length > 0;
        let finalInvoices = invoices;
        let boundTollsCount = 0;
        // 若 options.mergeTollsWithTaxi !== false（默认合并或明确指定合并）
        if (options.mergeTollsWithTaxi !== false) {
            const mergeRes = bindTollsToTaxiExpenses(invoices);
            finalInvoices = mergeRes.mergedItems;
            boundTollsCount = mergeRes.boundTollsCount;
            mergeRes.bindingLog;
        }
        else {
            // 独立逐条生成：过路费不与出租车合并，每张独立为单笔交通费记录
            finalInvoices = invoices.map(inv => {
                if (isTollInvoice(inv)) {
                    const clone = { ...inv };
                    clone.type = tripType === 'BUSINESS_TRIP' ? 'TRIP_TAXI' : 'TAXI';
                    clone.expenseTypeId = tripType === 'BUSINESS_TRIP' ? EXPENSE_TYPES.TRIP_TAXI.id : EXPENSE_TYPES.TAXI.id;
                    clone.expenseTypeName = tripType === 'BUSINESS_TRIP' ? EXPENSE_TYPES.TRIP_TAXI.name : EXPENSE_TYPES.TAXI.name;
                    clone.description = buildDescription('高速通行费/过路费');
                    clone.isModified = true;
                    return clone;
                }
                return inv;
            });
        }
        // 汇总文案
        let summaryText = '';
        if (tripSegments.length > 0) {
            summaryText = `⚡ 智能推断完成：已按行程表的 ${tripSegments.length} 个波次精准匹配并规划 ${modifiedCount} 项费用信息！\n` +
                `• 模式: ✈️ 异地出差 (多波次行程对齐)\n` +
                `• 行程波次: 共识别 ${tripSegments.length} 轮独立出差 (自动匹配各轮目的地、酒店及客户工厂)\n` +
                (project ? `• 关联项目: ${project}\n` : '') +
                (proxyPerson ? `• 代外驻报销: ${proxyPerson}\n` : '');
        }
        else {
            summaryText = `⚡ 智能推断完成：已规划 ${modifiedCount} 项费用信息！\n` +
                `• 模式: ${tripType === 'BUSINESS_TRIP' ? '✈️ 异地出差' : '🏢 市内通勤/拜访'}\n` +
                `• 公司基准: ${company} ⇄ 拜访客户: ${customer}\n` +
                (hotel ? `• 入住酒店: ${hotel}\n` : '') +
                (project ? `• 关联项目: ${project}\n` : '') +
                (proxyPerson ? `• 代外驻报销: ${proxyPerson}\n` : '');
        }
        if (boundTollsCount > 0) {
            summaryText += `\n• 🎫 发票合并: 已按时间窗口将 ${boundTollsCount} 笔过路费自动绑定至同程出租车费用中（1笔费用多张发票）`;
        }
        else if (hasConcurrentTolls && options.mergeTollsWithTaxi === false) {
            summaryText += `\n• 📄 独立生成: 已将 ${concurrentTolls.length} 笔过路费保持为独立费用记录（每张发票独立单笔）`;
        }
        if (uncertainDates.length > 0) {
            summaryText += `\n⚠️ 部分多程日期需人工留意核对: ${uncertainDates.join(', ')}`;
        }
        return {
            totalRecords: finalInvoices.length,
            modifiedCount,
            tripType,
            companyName: company,
            customerName: customer,
            hotelName: hotel,
            stationOrAirport: station,
            projectName: project,
            proxyPersonName: proxyPerson,
            missingFields,
            records: finalInvoices,
            boundTollsCount,
            hasConcurrentTolls,
            concurrentTollsCount: concurrentTolls.length,
            tollInquiryPrompt: (hasConcurrentTolls && options.mergeTollsWithTaxi === undefined) ? '发现有出租车发票同期的过路费是否合并生成？' : undefined,
            mergeTollsWithTaxi: options.mergeTollsWithTaxi,
            uncertainDates,
            summaryText,
            matchedTrips: tripSegments.length > 0 ? tripSegments : undefined
        };
    }

    let keepaliveTimer = null;
    let isPinging = false;
    let lastPingTime = 0;
    /**
     * 执行轻量级心跳请求，向系统服务端报活以刷新 Session 会话空闲倒计时 (30分钟超时防跌落)
     * 接口选用 YuanNian 极为轻量的只读接口：/expenseClaim/expenseRecord/countAlreadyRecoverExpenseRecord
     */
    async function touchSessionKeepalive(state, win) {
        if (isPinging)
            return true;
        isPinging = true;
        try {
            // 1. 每次心跳前动态嗅探提取最新 Token
            extractLatestTokens(state);
            // 2. 优先通过宿主原生 HTTP/Axios 客户端触发保活（与官方 UI 行为完全一致，该端点为 GET）
            let res = await callNativeHttp('/expenseClaim/expenseRecord/countAlreadyRecoverExpenseRecord', 'GET', null, win);
            // 3. 仅当原生客户端完全未连接时，降级使用备用 apiRequest 保活
            if (res === null) {
                res = await apiRequest('/fssc/expenseClaim/expenseRecord/countAlreadyRecoverExpenseRecord', 'GET', null, state);
            }
            const isSuccess = Boolean(res && res.success !== false && res.code !== '401');
            if (isSuccess) {
                lastPingTime = Date.now();
                AutopilotLogger.info(`[SessionKeepalive] 会话心跳保活成功，Session 空闲倒计时已刷新 (${new Date().toLocaleTimeString()})`);
            }
            else {
                AutopilotLogger.warn(`[SessionKeepalive] 会话心跳响应异常: ${res?.message || '未知状态'}`);
            }
            return isSuccess;
        }
        catch (err) {
            AutopilotLogger.warn(`[SessionKeepalive] 会话心跳保活失败: ${err.message}`);
            return false;
        }
        finally {
            isPinging = false;
        }
    }
    /**
     * 启动定时会话保活循环 (默认每 2.5 分钟保活一次，彻底杜绝长时间编辑导致的“登录失效”)
     */
    function startSessionKeepalive(state, intervalMs = 150000, win) {
        if (keepaliveTimer) {
            clearInterval(keepaliveTimer);
            keepaliveTimer = null;
        }
        AutopilotLogger.info(`[SessionKeepalive] 启动后台会话保活守护进程 (心跳间隔: ${Math.round(intervalMs / 1000)}s)`);
        // 立即执行一次初次保活与 Token 刷新
        touchSessionKeepalive(state, win);
        keepaliveTimer = setInterval(() => {
            touchSessionKeepalive(state, win);
        }, intervalMs);
    }

    async function mapConcurrent(items, concurrency, asyncFn) {
        const results = new Array(items.length);
        let currentIndex = 0;
        const worker = async () => {
            while (currentIndex < items.length) {
                const idx = currentIndex++;
                try {
                    results[idx] = await asyncFn(items[idx], idx);
                }
                catch (err) {
                    console.error(`Error in mapConcurrent at index ${idx}:`, err);
                    results[idx] = null;
                }
            }
        };
        const workers = [];
        const actualConcurrency = Math.min(concurrency, items.length);
        for (let i = 0; i < actualConcurrency; i++) {
            workers.push(worker());
        }
        await Promise.all(workers);
        return results;
    }

    /**
     * 将不同来源的发票对象统一解构并扁平化为标准化字段结构
     */
    function normalizeInvoiceData(raw) {
        if (!raw) {
            return {
                id: '',
                invoiceNo: '',
                invoiceCode: '',
                invoiceDate: '',
                amount: 0,
                typeName: '',
                sellerName: '',
                goodsName: '',
                timeGetOn: '',
                timeGetOff: '',
                detailChecked: false
            };
        }
        // 1. 如果是原生发票池行结构 (包含 datas 字典)
        if (raw.datas && typeof raw.datas === 'object') {
            const d = raw.datas;
            const res = {
                id: raw.boSourceRowId || raw.rowId || (d.ID ? d.ID.value : '') || '',
                invoiceNo: '',
                invoiceCode: '',
                invoiceDate: '',
                amount: 0,
                typeName: '',
                sellerName: '',
                goodsName: '',
                timeGetOn: '',
                timeGetOff: '',
                detailChecked: Boolean(raw.detailChecked)
            };
            Object.values(d).forEach((field) => {
                if (!field || !field.columnCode)
                    return;
                const code = field.columnCode;
                const val = field.value;
                if (code === 'INVOICE_NO') {
                    res.invoiceNo = (typeof val === 'string' ? val : (val ? String(val) : '')).trim();
                }
                else if (code === 'INVOICE_CODE') {
                    res.invoiceCode = (typeof val === 'string' ? val : (val ? String(val) : '')).trim();
                }
                else if (code === 'INVOICE_DATE') {
                    res.invoiceDate = normalizeDate(typeof val === 'string' ? val : (val ? String(val) : ''));
                }
                else if (code === 'AMOUNT_TAX' || code === 'TOTAL_AMOUNT') {
                    if (val && typeof val === 'object' && val.amount !== undefined) {
                        const parsed = parseFloat(val.amount);
                        if (!isNaN(parsed) && parsed > 0)
                            res.amount = parsed;
                    }
                    else if (val !== undefined && val !== null && typeof val !== 'object') {
                        const parsed = parseFloat(String(val).replace(/[^0-9.]/g, ''));
                        if (!isNaN(parsed) && parsed > 0)
                            res.amount = parsed;
                    }
                }
                else if (code === 'BO_TYPE_DEFINE_ID') {
                    if (val && typeof val === 'object') {
                        res.typeName = val.onlyTitle?.zh_CN || val.title?.zh_CN || val.name || '';
                    }
                    else if (typeof val === 'string') {
                        res.typeName = val;
                    }
                }
                else if (code === 'SELLER_NAME' || code === 'SALES_NAME') {
                    res.sellerName = (typeof val === 'string' ? val : '').trim();
                }
                else if (code === 'GOODS_NAME' || code === 'COMMODITY_NAME') {
                    res.goodsName = (typeof val === 'string' ? val : '').trim();
                }
            });
            // 二次回填：如果 AMOUNT_TAX 没取到有效值，再看 raw.datas 里有没有其他金额字段
            if (res.amount <= 0 && d.AMOUNT_TAX && d.AMOUNT_TAX.value) {
                const parsed = parseFloat(d.AMOUNT_TAX.value.amount || d.AMOUNT_TAX.value);
                if (!isNaN(parsed) && parsed > 0)
                    res.amount = parsed;
            }
            return res;
        }
        // 2. 如果是发票穿透详情 (invDetail / invoiceVO) 或标准 InvoiceItem
        const invVO = raw.invoiceVO || raw;
        const rawAmt = raw.amount !== undefined
            ? raw.amount
            : (invVO.amountTax !== undefined ? invVO.amountTax : (invVO.totalAmount !== undefined ? invVO.totalAmount : 0));
        const parsedAmt = typeof rawAmt === 'number' ? rawAmt : (parseFloat(String(rawAmt).replace(/[^0-9.]/g, '')) || 0);
        const rawDate = raw.invoiceDate || invVO.invoiceDate || raw.businessDate || '';
        const normDate = normalizeDate(typeof rawDate === 'string' ? rawDate : (rawDate ? String(rawDate) : ''));
        const no = (raw.invoiceNo || invVO.invoiceNo || invVO.invoiceNumber || '').trim();
        const code = (raw.invoiceCode || invVO.invoiceCode || '').trim();
        const typeName = raw.typeName || raw.expenseTypeName || invVO.invoiceTypeName || invVO.typeName || '';
        const seller = (raw.salesName || invVO.salesName || invVO.seller || invVO.sellerName || '').trim();
        const goods = (raw.invoiceDetails || invVO.goodsName || invVO.commodityNames || invVO.cargoInformation || '').trim();
        return {
            id: raw.id || raw.expenseRecordId || raw.boDataId || raw.boSourceRowId || invVO.invoiceDataId || '',
            invoiceNo: no,
            invoiceCode: code,
            invoiceDate: normDate,
            amount: parsedAmt,
            typeName,
            sellerName: seller,
            goodsName: goods,
            timeGetOn: raw.timeGetOn || invVO.timeGetOn || '',
            timeGetOff: raw.timeGetOff || invVO.timeGetOff || '',
            detailChecked: Boolean(raw.detailChecked || invVO.detailChecked)
        };
    }
    /**
     * 对单张发票执行完整性与合规校验
     */
    function validateSingleInvoice(rawInvoice) {
        const data = normalizeInvoiceData(rawInvoice);
        const issues = [];
        // 1. 发票金额校验 (🔴 阻断性必要字段)
        if (!data.amount || isNaN(data.amount) || data.amount <= 0) {
            issues.push({
                field: 'amount',
                severity: 'error',
                message: '发票金额未识别或金额为 0 元，请核实发票实付金额',
                shortBadge: '缺金额'
            });
        }
        // 2. 开票日期校验 (🔴 阻断性必要字段)
        if (!data.invoiceDate || data.invoiceDate.trim().length === 0) {
            issues.push({
                field: 'date',
                severity: 'error',
                message: '未识别到有效开票日期，报销与记费用必须具备开票日期',
                shortBadge: '缺日期'
            });
        }
        else {
            // 校验日期格式与合理年份 (避免 OCR 错识出如 2002 年、1990 年或未来年份)
            const dateMatch = data.invoiceDate.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})$/);
            if (!dateMatch) {
                issues.push({
                    field: 'date',
                    severity: 'error',
                    message: `开票日期格式非法 (${data.invoiceDate})，无法作为有效财务期间`,
                    shortBadge: '日期非法'
                });
            }
            else {
                const year = parseInt(dateMatch[1], 10);
                const month = parseInt(dateMatch[2], 10);
                const day = parseInt(dateMatch[3], 10);
                const currentYear = new Date().getFullYear();
                // 基础日历真实性校验
                const d = new Date(year, month - 1, day);
                if (isNaN(d.getTime()) || d.getFullYear() !== year || d.getMonth() !== month - 1 || d.getDate() !== day) {
                    issues.push({
                        field: 'date',
                        severity: 'error',
                        message: `开票日期(${data.invoiceDate})为无效日历日期`,
                        shortBadge: '无效日期'
                    });
                }
                else if (year < currentYear - 2) {
                    // 偏离 2 年以上（例如 2002 年），属于严重超期或 OCR 识别失真，阻断级错误
                    issues.push({
                        field: 'date',
                        severity: 'error',
                        message: `开票年份严重偏离当前财务期间 (${year}年)，可能为 OCR 识别失真或超期失效发票，请核验修改`,
                        shortBadge: '年份存疑'
                    });
                }
                else if (year < currentYear) {
                    // 上一年度跨年发票
                    issues.push({
                        field: 'date',
                        severity: 'warning',
                        message: `开票年份为往年 (${year}年)，请确认是否在跨年财务报销有效期内`,
                        shortBadge: '跨年发票'
                    });
                }
                else if (year > currentYear) {
                    issues.push({
                        field: 'date',
                        severity: 'error',
                        message: `开票年份为未来时间 (${year}年)，OCR 识别明显异常`,
                        shortBadge: '未来日期'
                    });
                }
            }
        }
        // 3. 发票号码校验 (🔴 阻断性必要字段)
        if (!data.invoiceNo || data.invoiceNo.trim().length === 0) {
            issues.push({
                field: 'invoiceNo',
                severity: 'error',
                message: '未识别到发票号码，系统无法进行发票查验与防重报销',
                shortBadge: '缺发票号'
            });
        }
        else if (data.invoiceNo.length < 4) {
            issues.push({
                field: 'invoiceNo',
                severity: 'warning',
                message: `发票号码位数过短 (${data.invoiceNo})，可能存在识别残缺`,
                shortBadge: '票号残缺'
            });
        }
        // 4. 发票类型校验 (🟡 建议完备字段)
        if (!data.typeName || data.typeName.includes('未识别') || data.typeName === 'OTHER' || data.typeName === 'None') {
            issues.push({
                field: 'invoiceType',
                severity: 'warning',
                message: '发票类型未明确归类，可能影响税率及报销科目自动匹配',
                shortBadge: '类型待定'
            });
        }
        // 5. 销售方与品名校验 (🟡 辅助校验：交通通行类票据免除此校验)
        const transportKeywords = [
            '出租车', '网约车', '客运', '火车', '铁路', '高铁', '动车',
            '机票', '航空', '行程单', '过路费', '通行费', '高速', 'ETC',
            '轮渡', '船票', '公交', '地铁', '轨道交通', '停车', '泊车', '客票'
        ];
        const isTransport = transportKeywords.some(kw => data.typeName.includes(kw));
        if (!isTransport && !data.sellerName && !data.goodsName) {
            issues.push({
                field: 'seller',
                severity: 'warning',
                message: '销售方名称与货物品名均未识别，建议点击修改补充',
                shortBadge: '缺销方品名'
            });
        }
        // 6. 出租车打车票乘车时间提示 (🟡 警示级提示：缺失将无法自动对齐差旅/考勤行程)
        // 状态守卫：仅当发票详情接口核验完毕 (detailChecked === true) 且确认未提取到上下车时间时才提示，杜绝未请求前抢跑误报
        if (data.typeName.includes('出租车')) {
            if (data.detailChecked) {
                if (!data.timeGetOn && !data.timeGetOff) {
                    issues.push({
                        field: 'time',
                        severity: 'warning',
                        message: '发票详情接口(/getBoDataAndTemplateWF)已核验：发票底层数据中未提取到上下车时间，无法自动对齐差旅与考勤行程，建议点击修改补充',
                        shortBadge: '缺乘车时间'
                    });
                }
            }
        }
        const hasErrors = issues.some(i => i.severity === 'error');
        const hasWarnings = issues.some(i => i.severity === 'warning');
        const errorBadges = issues
            .filter(i => i.severity === 'error')
            .map(i => i.shortBadge);
        const warningBadges = issues
            .filter(i => i.severity === 'warning')
            .map(i => i.shortBadge);
        const descList = [...errorBadges, ...warningBadges];
        const missingFieldsDesc = descList.length > 0 ? descList.join(' · ') : '信息完备';
        return {
            id: data.id,
            invoiceNo: data.invoiceNo,
            invoiceCode: data.invoiceCode,
            invoiceDate: data.invoiceDate,
            amount: data.amount,
            typeName: data.typeName,
            isValid: !hasErrors,
            hasWarnings: hasWarnings,
            issues,
            missingFieldsDesc
        };
    }
    /**
     * 批量校验发票列表并输出汇总结算体检报告
     */
    function validateInvoiceList(invoices) {
        const list = Array.isArray(invoices) ? invoices : [];
        const results = [];
        const invalidList = [];
        let missingAmountCount = 0;
        let missingDateCount = 0;
        let missingInvoiceNoCount = 0;
        let missingTypeCount = 0;
        let missingTimeCount = 0;
        let warningCount = 0;
        list.forEach(inv => {
            const res = validateSingleInvoice(inv);
            results.push(res);
            if (!res.isValid) {
                invalidList.push(res);
            }
            if (res.hasWarnings) {
                warningCount++;
            }
            res.issues.forEach(issue => {
                if (issue.severity === 'error') {
                    if (issue.field === 'amount')
                        missingAmountCount++;
                    if (issue.field === 'date')
                        missingDateCount++;
                    if (issue.field === 'invoiceNo')
                        missingInvoiceNoCount++;
                }
                else if (issue.field === 'invoiceType') {
                    missingTypeCount++;
                }
                else if (issue.field === 'time') {
                    missingTimeCount++;
                }
            });
        });
        return {
            totalCount: list.length,
            validCount: results.filter(r => r.isValid).length,
            invalidCount: invalidList.length,
            warningCount,
            missingAmountCount,
            missingDateCount,
            missingInvoiceNoCount,
            missingTypeCount,
            missingTimeCount,
            results,
            invalidList
        };
    }
    /**
     * 将校验结果回填并富化至 InvoiceItem 实体中
     */
    function enrichInvoiceWithValidation(item) {
        const report = validateSingleInvoice(item);
        item.validationIssues = report.issues;
        item.isValidInvoice = report.isValid;
        item.missingFieldsDesc = report.missingFieldsDesc;
        if (!report.isValid) {
            item.status = '残缺';
        }
        return item;
    }

    function normalizeTimeHelper(t) {
        if (!t)
            return '';
        const clean = t.toString().trim();
        const parts = clean.split(':');
        if (parts.length >= 2) {
            return `${parts[0].trim().padStart(2, '0')}:${parts[1].trim().padStart(2, '0')}`;
        }
        return clean;
    }
    function sortInvoices(list) {
        return list.sort((a, b) => {
            const dateA = normalizeDate(a.invoiceDate || '') || '9999-99-99';
            const dateB = normalizeDate(b.invoiceDate || '') || '9999-99-99';
            if (dateA !== dateB)
                return dateA.localeCompare(dateB);
            const timeA = normalizeTimeHelper(a.timeGetOn) || '99:99';
            const timeB = normalizeTimeHelper(b.timeGetOn) || '99:99';
            return timeA.localeCompare(timeB);
        });
    }
    /**
     * 全量同步发票夹与未报销费用记录列表（带多级容灾与 DOM 降级兜底）
     */
    async function loadAllInvoicesAndExpenses(state) {
        // 0. 刷新当前真实登录人信息
        try {
            await fetchLoginUserInfo(state);
        }
        catch (e) { }
        const loaded = [];
        const processedRecordIds = new Set();
        const processedInvoiceDataIds = new Set();
        const processedInvoiceNos = new Set();
        // 1. 发票夹池
        const poolList = await queryInvoicePoolListApi(state);
        const poolInvoices = await mapConcurrent(poolList, 8, async (pItem) => {
            const dataId = pItem.boSourceRowId || (pItem.datas && pItem.datas.ID ? pItem.datas.ID.value : '');
            if (!dataId)
                return null;
            try {
                const invDetail = await getInvoiceDetailByDataIdApi(dataId, state);
                return { dataId, invDetail, pItem };
            }
            catch (e) {
                return null;
            }
        });
        const invoiceOcrMap = new Map();
        poolInvoices.forEach(item => {
            if (!item || !item.invDetail)
                return;
            const inv = item.invDetail;
            if (inv.invoiceNo)
                invoiceOcrMap.set(inv.invoiceNo, inv);
            if (item.dataId)
                invoiceOcrMap.set(item.dataId, inv);
            if (inv.invoiceDate && inv.amountTax !== undefined) {
                invoiceOcrMap.set(`${normalizeDate(inv.invoiceDate)}_${inv.amountTax}`, inv);
            }
        });
        // 2. 未报销费用明细
        const recordList = await queryExpenseRecordListApi(state);
        const parsedRecords = await mapConcurrent(recordList, 8, async (item) => {
            const recId = item.expenseRecordId;
            if (!recId)
                return null;
            try {
                const ruleData = await getExpenseTypeRuleAndRowDatasApi(recId, item.expenseTypeId || 'UNIDENTIFIED', state);
                const rowDatas = ruleData.rowDatas || {};
                const v = ruleData.version || 1;
                let invVO = {};
                const invListField = rowDatas.expenseRecordInvoiceList;
                if (invListField && invListField.value && invListField.value.length > 0) {
                    invVO = invListField.value[0].invoiceVO || {};
                }
                let matchedInv = null;
                if (invVO.invoiceNo && invoiceOcrMap.has(invVO.invoiceNo))
                    matchedInv = invoiceOcrMap.get(invVO.invoiceNo);
                else if (invVO.invoiceDataId && invoiceOcrMap.has(invVO.invoiceDataId))
                    matchedInv = invoiceOcrMap.get(invVO.invoiceDataId);
                else if (item.businessDate && item.amountObj) {
                    const key = `${normalizeDate(item.businessDate)}_${item.amountObj.amount}`;
                    if (invoiceOcrMap.has(key))
                        matchedInv = invoiceOcrMap.get(key);
                }
                if (matchedInv) {
                    if (!invVO.timeGetOn && matchedInv.timeGetOn)
                        invVO.timeGetOn = matchedInv.timeGetOn;
                    if (!invVO.timeGetOff && matchedInv.timeGetOff)
                        invVO.timeGetOff = matchedInv.timeGetOff;
                    if (!invVO.mileage && matchedInv.mileage)
                        invVO.mileage = matchedInv.mileage;
                    if (!invVO.salesName && (matchedInv.salesName || matchedInv.seller))
                        invVO.salesName = matchedInv.salesName || matchedInv.seller;
                    if (!invVO.seller && (matchedInv.seller || matchedInv.salesName))
                        invVO.seller = matchedInv.seller || matchedInv.salesName;
                    if (!invVO.invoiceNo && matchedInv.invoiceNo)
                        invVO.invoiceNo = matchedInv.invoiceNo;
                    if (!invVO.invoiceCode && matchedInv.invoiceCode)
                        invVO.invoiceCode = matchedInv.invoiceCode;
                    if (matchedInv.invoiceDataId)
                        invVO.invoiceDataId = matchedInv.invoiceDataId;
                    if (!invVO.commodityNames && matchedInv.commodityNames)
                        invVO.commodityNames = matchedInv.commodityNames;
                    if (!invVO.cargoInformation && matchedInv.cargoInformation)
                        invVO.cargoInformation = matchedInv.cargoInformation;
                    if (!invVO.invoiceDetails && matchedInv.invoiceDetails)
                        invVO.invoiceDetails = matchedInv.invoiceDetails;
                    if (!invVO.goodsName && matchedInv.goodsName)
                        invVO.goodsName = matchedInv.goodsName;
                    if (!invVO.invoiceTypeAbbreviation && matchedInv.invoiceTypeAbbreviation)
                        invVO.invoiceTypeAbbreviation = matchedInv.invoiceTypeAbbreviation;
                    if (!invVO.invoiceTypeCode && matchedInv.invoiceTypeCode)
                        invVO.invoiceTypeCode = matchedInv.invoiceTypeCode;
                }
                let attachList = [];
                if (rowDatas.expenseRecordAttachmentList && rowDatas.expenseRecordAttachmentList.value) {
                    attachList = rowDatas.expenseRecordAttachmentList.value;
                }
                const cat = detectInvoiceCategory(invVO, item, item.expenseTypeName || '');
                const rawDate = invVO.invoiceDate || (item.businessDate ? item.businessDate.split(' ')[0] : '');
                const invDate = normalizeDate(rawDate);
                const amt = item.amountObj ? item.amountObj.amount : (invVO.amountTax || 0);
                const isComm = cat === 'COMMUNICATION';
                let cleanPeriod = '';
                const existingPeriod = (rowDatas.F_ZY_DEF_001 ? rowDatas.F_ZY_DEF_001.value : '').replace(/^期间[：:]\s*/, '').trim();
                cleanPeriod = (existingPeriod && existingPeriod.length === 7) ? existingPeriod : computePeriod(invDate, isComm);
                return {
                    expenseRecordId: recId,
                    version: v,
                    invoiceVO: invVO,
                    invoiceNo: invVO.invoiceNo || '',
                    invoiceCode: invVO.invoiceCode || '',
                    invoiceDate: invDate,
                    fileName: invVO.fileName || '',
                    salesName: invVO.salesName || invVO.seller || '',
                    timeGetOn: normalizeTimeHelper(invVO.timeGetOn),
                    timeGetOff: normalizeTimeHelper(invVO.timeGetOff),
                    mileage: invVO.mileage ? `${invVO.mileage}km` : '',
                    amount: amt,
                    type: cat,
                    expenseTypeId: item.expenseTypeId || '',
                    expenseTypeName: item.expenseTypeName || '',
                    startAddress: rowDatas.START_ADDRESS ? (rowDatas.START_ADDRESS.value || '') : '',
                    endAddress: rowDatas.END_ADDRESS ? (rowDatas.END_ADDRESS.value || '') : '',
                    description: item.description || (rowDatas.DESCRIPTION ? rowDatas.DESCRIPTION.value || '' : ''),
                    period: cleanPeriod,
                    attachments: attachList,
                    errorMessages: item.expenseRecordTypeMessageVO?.errorMessages || [],
                    status: (item.expenseRecordTypeMessageVO?.errorMessages && item.expenseRecordTypeMessageVO.errorMessages.length > 0)
                        ? '异常'
                        : ((item.expenseTypeName && item.expenseTypeName !== 'None') ? '成功' : '就绪')
                };
            }
            catch (e) {
                AutopilotLogger.warn(`[ExpenseService] 解析单笔费用记录详情异常 (${recId}): ${e.message}`);
                const invDate = normalizeDate(item.businessDate ? item.businessDate.split(' ')[0] : '');
                const amt = item.amountObj ? item.amountObj.amount : 0;
                const fallbackCat = detectInvoiceCategory({}, item, item.expenseTypeName || '');
                return {
                    expenseRecordId: recId,
                    version: item.version || 1,
                    invoiceVO: {},
                    invoiceNo: '',
                    invoiceCode: '',
                    invoiceDate: invDate,
                    timeGetOn: '',
                    timeGetOff: '',
                    mileage: '',
                    amount: amt,
                    type: fallbackCat !== 'OTHER' ? fallbackCat : (amt >= 350 ? 'HOTEL' : 'TAXI'),
                    startAddress: '',
                    endAddress: '',
                    description: item.description || '',
                    period: computePeriod(invDate, false),
                    attachments: [],
                    errorMessages: item.expenseRecordTypeMessageVO?.errorMessages || [],
                    status: (item.expenseRecordTypeMessageVO?.errorMessages && item.expenseRecordTypeMessageVO.errorMessages.length > 0) ? '异常' : '就绪'
                };
            }
        });
        parsedRecords.forEach(r => {
            if (r) {
                loaded.push(r);
                if (r.expenseRecordId)
                    processedRecordIds.add(r.expenseRecordId);
                if (r.invoiceVO && r.invoiceVO.invoiceDataId)
                    processedInvoiceDataIds.add(r.invoiceVO.invoiceDataId);
                if (r.invoiceNo)
                    processedInvoiceNos.add(r.invoiceNo);
            }
        });
        poolInvoices.forEach(item => {
            if (!item || !item.invDetail)
                return;
            const invDetail = item.invDetail;
            const dataId = item.dataId;
            const invNo = invDetail.invoiceNo || '';
            if (processedInvoiceDataIds.has(dataId) || (invNo && processedInvoiceNos.has(invNo)))
                return;
            const invDate = normalizeDate(invDetail.invoiceDate || '');
            const amt = invDetail.amountTax !== undefined ? invDetail.amountTax : 0;
            const cat = detectInvoiceCategory(invDetail, {}, '');
            const isComm = cat === 'COMMUNICATION';
            loaded.push({
                expenseRecordId: '',
                version: 1,
                boDataId: dataId,
                invoiceVO: invDetail,
                invoiceNo: invNo,
                invoiceCode: invDetail.invoiceCode || '',
                invoiceDate: invDate,
                timeGetOn: normalizeTimeHelper(invDetail.timeGetOn),
                timeGetOff: normalizeTimeHelper(invDetail.timeGetOff),
                mileage: invDetail.mileage ? `${invDetail.mileage}km` : '',
                amount: amt,
                type: cat,
                startAddress: '',
                endAddress: '',
                description: '',
                period: computePeriod(invDate, isComm),
                attachments: [],
                status: '待流转'
            });
        });
        // 智能容灾层 1：若发票池和费用记录均为 0，检测是否在报销单编辑页 (#billWrite)
        if (loaded.length === 0) {
            let billMainId = state.currentBillMainId;
            if (!billMainId && typeof window !== 'undefined') {
                const hash = window.location.hash || '';
                const match = hash.match(/billMainId=([a-zA-Z0-9_\-]+)/) || hash.match(/id=([a-zA-Z0-9_\-]+)/);
                if (match)
                    billMainId = match[1];
                if (!billMainId) {
                    const search = window.location.search || '';
                    const m2 = search.match(/billMainId=([a-zA-Z0-9_\-]+)/) || search.match(/id=([a-zA-Z0-9_\-]+)/);
                    if (m2)
                        billMainId = m2[1];
                }
            }
            if (billMainId && (!state.billRows || state.billRows.length === 0)) {
                try {
                    const { billData } = await fetchBillDataAndTemplateApi(billMainId, state);
                    state.currentBillData = billData;
                    const parsed = parseBillDataStructure(billData);
                    state.billRows = parsed.billRows;
                    state.billTags = parsed.billTags;
                }
                catch (e) {
                    AutopilotLogger.warn(`[ExpenseService] 自动拉取报销单明细行失败: ${e.message}`);
                }
            }
            if (state.billRows && state.billRows.length > 0) {
                state.billRows.forEach((row, idx) => {
                    loaded.push({
                        id: row.claimRowId || `bill-row-${idx}`,
                        expenseRecordId: row.claimRowId,
                        version: 1,
                        invoiceVO: {},
                        invoiceNo: '',
                        invoiceCode: '',
                        invoiceDate: '',
                        timeGetOn: '',
                        timeGetOff: '',
                        mileage: '',
                        amount: row.amount,
                        type: detectInvoiceCategory({}, {}, row.expTypeName),
                        expenseTypeName: row.expTypeName || '市内交通费',
                        startAddress: '',
                        endAddress: '',
                        description: row.recDesc || '',
                        period: '',
                        attachments: [],
                        status: '就绪',
                        isModified: false
                    });
                });
            }
        }
        // 智能融合层：从当前宿主页面 DOM / React Fiber 中增量融合发票（保障 100% 提取发票夹全部发票）
        const domItems = scrapeInvoicesFromDom();
        if (domItems.length > 0) {
            domItems.forEach(d => {
                const dataId = d.boDataId || d.id;
                const invNo = d.invoiceNo || '';
                if (dataId && processedInvoiceDataIds.has(dataId))
                    return;
                if (invNo && processedInvoiceNos.has(invNo))
                    return;
                loaded.push(d);
                if (dataId)
                    processedInvoiceDataIds.add(dataId);
                if (invNo)
                    processedInvoiceNos.add(invNo);
            });
        }
        const sorted = sortInvoices(loaded);
        // 对每条发票执行完整性体检与残缺字段标记
        sorted.forEach(item => enrichInvoiceWithValidation(item));
        state.invoices = sorted;
        state.selectedIndices.clear();
        sorted.forEach((_, idx) => state.selectedIndices.add(idx));
        return sorted;
    }
    /**
     * 宿主页面 DOM 表格穿透兜底爬取
     * 当后端接口因权限、状态过滤返回 0 条时，直接从用户屏幕可见的表格中提取数据
     */
    function scrapeInvoicesFromDom(state) {
        if (typeof document === 'undefined')
            return [];
        const results = [];
        const seenIds = new Set();
        const seenNos = new Set();
        // 辅助：从 DOM 节点探测 React Fiber
        function findFiber(el) {
            if (!el)
                return null;
            const key = Object.keys(el).find(k => k.startsWith('__reactInternalInstance$') || k.startsWith('__reactFiber$'));
            return key ? el[key] : null;
        }
        // 辅助：从单个 document 中提取 React Table dataSource
        function extractFromDocFiber(doc) {
            if (!doc)
                return null;
            const trs = Array.from(doc.querySelectorAll('tbody tr'));
            for (const tr of trs) {
                let fiber = findFiber(tr);
                while (fiber) {
                    if (fiber.memoizedProps?.dataSource && Array.isArray(fiber.memoizedProps.dataSource) && fiber.memoizedProps.dataSource.length > 0) {
                        return fiber.memoizedProps.dataSource;
                    }
                    fiber = fiber.return;
                }
            }
            return null;
        }
        // 收集主文档及所有同源 iframe 文档
        const docs = [document];
        document.querySelectorAll('iframe').forEach(f => {
            try {
                const d = f.contentDocument || f.contentWindow?.document;
                if (d && !docs.includes(d))
                    docs.push(d);
            }
            catch (e) { }
        });
        // 辅助：从 Fiber 节点数据对象中按 columnCode 动态提取值
        function getColumnValue(record, code) {
            if (!record || typeof record !== 'object')
                return undefined;
            if (record[code]?.value !== undefined)
                return record[code].value;
            for (const key of Object.keys(record)) {
                const item = record[key];
                if (item && typeof item === 'object' && item.columnCode === code) {
                    return item.value;
                }
            }
            return undefined;
        }
        // 1. 优先从 React Fiber 提取最完整的发票池原生数据 (穿透发票夹 iframe 与宿主页面)
        for (const doc of docs) {
            const dataSource = extractFromDocFiber(doc);
            if (dataSource && dataSource.length > 0) {
                for (let idx = 0; idx < dataSource.length; idx++) {
                    const d = dataSource[idx];
                    const dataId = d.ID?.value || d.boSourceRowId?.value || d.boSourceRowId || getColumnValue(d, 'ID') || `inv-fiber-${idx}`;
                    const typeName = d.BO_TYPE_DEFINE_ID?.value?.onlyTitle?.zh_CN || d.BO_TYPE_DEFINE_ID?.value?.title?.zh_CN || d.BO_TYPE_DEFINE_ID?.title?.zh_CN || '';
                    const invCode = getColumnValue(d, 'INVOICE_CODE') || d['8f8eb6197a4411e9b0eddf7f464b08f2']?.value || '';
                    const invNo = getColumnValue(d, 'INVOICE_NO') || d['9b1993717a4411e9b0ed17d010f97c63']?.value || '';
                    const rawDate = getColumnValue(d, 'INVOICE_DATE') || d['ba31ef167a4411e9b0ed9162dd502459']?.value || '';
                    const invDate = normalizeDate(rawDate);
                    const taxAmtObj = getColumnValue(d, 'AMOUNT_TAX') ?? d['d3f7fcbc7a4411e9b0ed576d29ce88e9']?.value;
                    const amt = typeof taxAmtObj === 'object' ? (taxAmtObj?.amount ?? 0) : (Number(taxAmtObj) || 0);
                    const rawSales = getColumnValue(d, 'SALES_NAME');
                    const salesName = typeof rawSales === 'string' ? rawSales : (rawSales?.title?.zh_CN || rawSales?.[0]?.title?.zh_CN || '');
                    const rawPurchaser = getColumnValue(d, 'PURCHASER_NAME');
                    const purchaserName = typeof rawPurchaser === 'string' ? rawPurchaser : (rawPurchaser?.title?.zh_CN || rawPurchaser?.[0]?.title?.zh_CN || '');
                    if (seenIds.has(dataId) || (invNo && seenNos.has(invNo)))
                        continue;
                    if (dataId)
                        seenIds.add(dataId);
                    if (invNo)
                        seenNos.add(invNo);
                    const invoiceVO = {
                        invoiceDataId: dataId,
                        invoiceNo: invNo,
                        invoiceCode: invCode,
                        invoiceDate: invDate,
                        amountTax: amt,
                        salesName: salesName,
                        seller: salesName,
                        purchaserName: purchaserName,
                        invoiceTypeAbbreviation: typeName,
                        commodityNames: typeName,
                        fileName: `${invDate}_${typeName}_¥${amt}`
                    };
                    const cat = detectInvoiceCategory(invoiceVO, {}, typeName);
                    const isComm = cat === 'COMMUNICATION';
                    results.push({
                        id: dataId,
                        boDataId: dataId,
                        expenseRecordId: '',
                        version: 1,
                        invoiceVO: invoiceVO,
                        invoiceNo: invNo,
                        invoiceCode: invCode,
                        invoiceDate: invDate,
                        salesName: salesName,
                        timeGetOn: '',
                        timeGetOff: '',
                        mileage: '',
                        amount: amt,
                        type: cat,
                        expenseTypeName: typeName || (cat === 'HOTEL' ? '住宿费' : cat === 'FLIGHT' ? '飞机票' : cat === 'TRAIN' ? '火车票' : '市内交通费'),
                        startAddress: '',
                        endAddress: '',
                        description: '',
                        period: computePeriod(invDate, isComm),
                        attachments: [],
                        status: '待流转',
                        isModified: false
                    });
                }
                if (results.length > 0) {
                    AutopilotLogger.info(`[ExpenseService] 成功通过 React Fiber 穿透提取发票池数据 (${results.length} 笔记录)`);
                    return results;
                }
            }
        }
        // 2. 降级：从 HTML 表格 DOM 中爬取
        for (const doc of docs) {
            const allTables = Array.from(doc.querySelectorAll('table')).filter(t => {
                const id = t.id || '';
                const cls = t.className || '';
                return !id.includes('yn-') && !cls.includes('webmcp') && !id.includes('webmcp') && !id.includes('trip-');
            });
            for (const table of allTables) {
                const rows = Array.from(table.querySelectorAll('tbody tr'));
                if (rows.length === 0)
                    continue;
                const headers = Array.from(table.querySelectorAll('thead th, thead td')).map(h => (h.textContent || '').trim());
                const dateColIdx = headers.findIndex(h => /日期|时间|date/i.test(h));
                const typeColIdx = headers.findIndex(h => /类型|类别|科目|type|category/i.test(h));
                const amtColIdx = headers.findIndex(h => /金额|价税|含税|amount|price/i.test(h));
                const descColIdx = headers.findIndex(h => /说明|事由|描述|备注|desc/i.test(h));
                const startColIdx = headers.findIndex(h => /出发|起点|origin|from/i.test(h));
                const endColIdx = headers.findIndex(h => /到达|目的|destination|to/i.test(h));
                const invNoColIdx = headers.findIndex(h => /发票号|单据号|no|code/i.test(h));
                for (let i = 0; i < rows.length; i++) {
                    const tr = rows[i];
                    const cells = Array.from(tr.querySelectorAll('td'));
                    if (cells.length < 3)
                        continue;
                    const getCellText = (idx) => (idx !== -1 && idx < cells.length ? (cells[idx].textContent || '').trim() : '');
                    const fullRowText = cells.map(c => c.textContent || '').join(' ');
                    let invDate = '';
                    if (dateColIdx !== -1) {
                        invDate = normalizeDate(getCellText(dateColIdx));
                    }
                    if (!invDate) {
                        const m = fullRowText.match(/\b(20\d{2}[-/.]\d{1,2}[-/.]\d{1,2})\b/);
                        if (m)
                            invDate = normalizeDate(m[1]);
                    }
                    let amount = 0;
                    if (amtColIdx !== -1) {
                        const amtStr = getCellText(amtColIdx).replace(/[^\d.]/g, '');
                        amount = parseFloat(amtStr) || 0;
                    }
                    if (!amount) {
                        const m = fullRowText.match(/(?:¥|￥)\s*(\d+(?:\.\d{1,2})?)/);
                        if (m)
                            amount = parseFloat(m[1]) || 0;
                    }
                    const typeName = typeColIdx !== -1 ? getCellText(typeColIdx) : '';
                    const cat = detectInvoiceCategory({}, {}, typeName || fullRowText);
                    let startAddress = startColIdx !== -1 ? getCellText(startColIdx) : '';
                    let endAddress = endColIdx !== -1 ? getCellText(endColIdx) : '';
                    if (!startAddress && !endAddress) {
                        const m = fullRowText.match(/([^\s,，]+)\s*(?:至|➔|->|-->|到)\s*([^\s,，]+)/);
                        if (m) {
                            startAddress = m[1].trim();
                            endAddress = m[2].trim();
                        }
                    }
                    const description = descColIdx !== -1 ? getCellText(descColIdx) : '';
                    const invoiceNo = invNoColIdx !== -1 ? getCellText(invNoColIdx) : '';
                    const rowId = tr.getAttribute('data-id') || tr.getAttribute('row-key') || tr.getAttribute('id') || `dom-row-${i}`;
                    if (amount > 0 || invDate || typeName) {
                        results.push({
                            id: rowId,
                            expenseRecordId: rowId,
                            version: 1,
                            invoiceVO: {},
                            invoiceNo: invoiceNo,
                            invoiceCode: '',
                            invoiceDate: invDate,
                            timeGetOn: '',
                            timeGetOff: '',
                            mileage: '',
                            amount,
                            type: cat,
                            expenseTypeName: typeName || (cat === 'HOTEL' ? '住宿费' : cat === 'FLIGHT' ? '飞机票' : cat === 'TRAIN' ? '火车票' : '市内交通费'),
                            startAddress,
                            endAddress,
                            description,
                            period: computePeriod(invDate, cat === 'COMMUNICATION'),
                            attachments: [],
                            status: '待流转',
                            isModified: false
                        });
                    }
                }
                if (results.length > 0)
                    break;
            }
            if (results.length > 0)
                break;
        }
        if (results.length > 0) {
            AutopilotLogger.info(`[ExpenseService] 从宿主 DOM 表格中兜底爬取成功 (${results.length} 笔记录)`);
        }
        return results;
    }
