        const btnProj = card.querySelector(`#${widgetId}-btn-proj`);
        const projSection = card.querySelector(`#${widgetId}-proj-section`);
        const searchInput = card.querySelector(`#${widgetId}-search-input`);
        const searchClear = card.querySelector(`#${widgetId}-search-clear`);
